-- Aprenda se Divertindo · 74 · Baralho de cartões de estudo · trilha Policial (500 cartões)
-- Rode depois do 73-simulado-domingo.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- O que muda:
--   • Os cartões de estudo da trilha Policial deixam de ser as questões do jogo e passam a vir deste baralho próprio,
--     feito para memorizar: pergunta curta, lacuna da lei, certo ou errado e "qual a diferença", sempre com a base legal.
--   • As revisões que cada pessoa já tinha dos cartões antigos continuam normalmente até ela dominá-los.
--   • Os cartões têm números a partir de 2.000.000.001, para não se misturar com as questões do jogo nem com as criadas pela administração.
--   • Para desativar um cartão: update public.cartoes set ativa = false where id = NÚMERO;

create table if not exists public.cartoes (
  id            integer primary key check (id >= 2000000000),
  trilha        text not null,
  materia       text not null,
  assunto       text not null default '',
  tipo          text not null default 'pergunta' check (tipo in ('pergunta','lacuna','certo_errado','pares')),
  frente        text not null,
  verso         text not null,
  explicacao    text not null default '',
  ativa         boolean not null default true,
  atualizado_em timestamptz not null default now()
);
create index if not exists cartoes_trilha on public.cartoes (trilha) where ativa;
-- se uma versão anterior deste arquivo já foi rodada (cartões numerados a partir de 1.000.001), troca para a faixa nova
delete from public.cartoes where id < 2000000000;
alter table public.cartoes drop constraint if exists cartoes_id_check;
alter table public.cartoes add constraint cartoes_id_check check (id >= 2000000000);

alter table public.cartoes enable row level security;
drop policy if exists "cartoes visiveis" on public.cartoes;
create policy "cartoes visiveis" on public.cartoes for select to anon, authenticated using (ativa);
revoke insert, update, delete on public.cartoes from anon, authenticated;
grant select on public.cartoes to anon, authenticated;

-- "impressão digital" do baralho: o jogo só baixa os cartões de novo quando algo muda
create or replace function public.cartoes_versao()
returns text language sql stable security definer set search_path = '' as $$
  select md5(coalesce(string_agg(md5(concat_ws('|', id, trilha, materia, assunto, tipo, frente, verso, explicacao, ativa)), '' order by id), ''))
  from public.cartoes;
$$;
revoke all on function public.cartoes_versao() from public;
grant execute on function public.cartoes_versao() to anon, authenticated;

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000000001, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "lacuna", "frente": "“Não há crime sem lei ____ que o defina, nem pena sem prévia cominação legal.”", "verso": "anterior", "explicacao": "Princípio da legalidade e da anterioridade: CF, art. 5º, XXXIX, e CP, art. 1º."}, {"id": 2000000002, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "A lei penal mais benéfica retroage mesmo depois do trânsito em julgado?", "verso": "Sim. Retroage para beneficiar o réu, ainda que já condenado em definitivo.", "explicacao": "CP, art. 2º, parágrafo único, e CF, art. 5º, XL."}, {"id": 2000000003, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Na abolitio criminis, o que acontece com os efeitos civis da condenação?", "verso": "Continuam. Cessam a execução e os efeitos penais, mas os efeitos civis (como o dever de indenizar) permanecem.", "explicacao": "CP, art. 2º, caput."}, {"id": 2000000004, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Qual teoria o Código Penal adota para o TEMPO do crime?", "verso": "Teoria da atividade: considera-se praticado o crime no momento da ação ou omissão, ainda que outro seja o resultado.", "explicacao": "CP, art. 4º. Mnemônico LUTA: Lugar = Ubiquidade; Tempo = Atividade."}, {"id": 2000000005, "trilha": "policial", "materia": "pen", "assunto": "Lei penal", "tipo": "pergunta", "frente": "Qual teoria o Código Penal adota para o LUGAR do crime?", "verso": "Teoria da ubiquidade: lugar da ação ou omissão, no todo ou em parte, e também onde se produziu ou deveria produzir-se o resultado.", "explicacao": "CP, art. 6º. Mnemônico LUTA."}, {"id": 2000000006, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Pelo conceito analítico tripartido, crime é:", "verso": "Fato típico, ilícito (antijurídico) e culpável.", "explicacao": "Teoria tripartida, majoritária na doutrina e cobrada pelas bancas."}, {"id": 2000000007, "trilha": "policial", "materia": "pen", "assunto": "Teoria do crime", "tipo": "pergunta", "frente": "Quais são os elementos do fato típico?", "verso": "Conduta, resultado, nexo causal e tipicidade.", "explicacao": "Nos crimes formais e de mera conduta, o resultado naturalístico não é exigido para a consumação."}, {"id": 2000000008, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "pergunta", "frente": "Quais são as quatro excludentes de ilicitude do art. 23 do CP?", "verso": "Estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.", "explicacao": "CP, art. 23. O excesso doloso ou culposo é punível (parágrafo único)."}, {"id": 2000000009, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "lacuna", "frente": "Legítima defesa: quem, usando moderadamente dos meios necessários, repele injusta agressão, ____ ou iminente, a direito seu ou de outrem.", "verso": "atual", "explicacao": "CP, art. 25. Agressão futura ou passada não autoriza legítima defesa."}, {"id": 2000000010, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "certo_errado", "frente": "Certo ou errado? Considera-se em legítima defesa o agente de segurança pública que repele agressão ou risco de agressão a vítima mantida refém durante a prática de crimes.", "verso": "Certo.", "explicacao": "CP, art. 25, parágrafo único, incluído pelo Pacote Anticrime (Lei 13.964/2019)."}, {"id": 2000000011, "trilha": "policial", "materia": "pen", "assunto": "Excludentes", "tipo": "pergunta", "frente": "Quem tem o dever legal de enfrentar o perigo (ex.: bombeiro) pode alegar estado de necessidade?", "verso": "Não.", "explicacao": "CP, art. 24, § 1º."}, {"id": 2000000012, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pares", "frente": "Qual a diferença entre dolo direto e dolo eventual?", "verso": "Dolo direto: o agente quer o resultado. Dolo eventual: o agente prevê o resultado e assume o risco de produzi-lo.", "explicacao": "CP, art. 18, I."}, {"id": 2000000013, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pares", "frente": "Qual a diferença entre culpa consciente e dolo eventual?", "verso": "Nos dois o agente prevê o resultado. Na culpa consciente, acredita sinceramente que ele não vai acontecer; no dolo eventual, aceita que aconteça (“tanto faz”).", "explicacao": "Diferença clássica de prova: a previsão existe nas duas; o que muda é a aceitação do resultado."}, {"id": 2000000014, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "pergunta", "frente": "Quais são as três modalidades de culpa?", "verso": "Imprudência (agir sem cautela), negligência (deixar de agir com cautela) e imperícia (falta de aptidão técnica).", "explicacao": "CP, art. 18, II."}, {"id": 2000000015, "trilha": "policial", "materia": "pen", "assunto": "Dolo e culpa", "tipo": "certo_errado", "frente": "Certo ou errado? Todo crime admite a forma culposa.", "verso": "Errado. Só se pune a forma culposa quando a lei a prevê expressamente.", "explicacao": "CP, art. 18, parágrafo único (excepcionalidade do crime culposo)."}, {"id": 2000000016, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "Qual é a redução de pena na tentativa?", "verso": "De um a dois terços.", "explicacao": "CP, art. 14, parágrafo único. Quanto mais perto da consumação, menor a redução."}, {"id": 2000000017, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pares", "frente": "Qual a diferença entre desistência voluntária e arrependimento eficaz?", "verso": "Desistência: o agente para no meio da execução. Arrependimento eficaz: termina a execução, mas age para impedir o resultado. Nos dois, responde só pelos atos já praticados.", "explicacao": "CP, art. 15. São a “ponte de ouro”."}, {"id": 2000000018, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "Quais os requisitos do arrependimento posterior?", "verso": "Crime sem violência ou grave ameaça à pessoa, reparação do dano ou restituição da coisa, por ato voluntário, até o recebimento da denúncia ou queixa. Reduz a pena de 1/3 a 2/3.", "explicacao": "CP, art. 16. É a “ponte de prata”."}, {"id": 2000000019, "trilha": "policial", "materia": "pen", "assunto": "Iter criminis", "tipo": "pergunta", "frente": "O que é crime impossível?", "verso": "Quando, por ineficácia absoluta do meio ou absoluta impropriedade do objeto, é impossível consumar o crime. Não se pune nem a tentativa.", "explicacao": "CP, art. 17. Ex.: tentar matar quem já estava morto."}, {"id": 2000000020, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Erro de tipo: qual o efeito quando é inevitável e quando é evitável?", "verso": "Inevitável: exclui dolo e culpa. Evitável: exclui o dolo, mas permite punir por culpa, se houver forma culposa.", "explicacao": "CP, art. 20."}, {"id": 2000000021, "trilha": "policial", "materia": "pen", "assunto": "Erro", "tipo": "pares", "frente": "Erro de proibição: qual o efeito quando é inevitável e quando é evitável?", "verso": "Inevitável: isenta de pena. Evitável: reduz a pena de 1/6 a 1/3.", "explicacao": "CP, art. 21. O desconhecimento da lei é inescusável."}, {"id": 2000000022, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "Na coação moral irresistível, quem é punido?", "verso": "Só o autor da coação.", "explicacao": "CP, art. 22. Exclui a culpabilidade do coagido (inexigibilidade de conduta diversa)."}, {"id": 2000000023, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "A partir de que idade a pessoa é penalmente imputável?", "verso": "18 anos. Os menores ficam sujeitos à legislação especial (ECA).", "explicacao": "CP, art. 27, e CF, art. 228."}, {"id": 2000000024, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "certo_errado", "frente": "Certo ou errado? A emoção e a paixão excluem a imputabilidade penal.", "verso": "Errado.", "explicacao": "CP, art. 28, I. Podem, no máximo, atenuar a pena ou privilegiar o homicídio."}, {"id": 2000000025, "trilha": "policial", "materia": "pen", "assunto": "Culpabilidade", "tipo": "pergunta", "frente": "Que tipo de embriaguez completa isenta de pena?", "verso": "A proveniente de caso fortuito ou força maior. A voluntária ou culposa não exclui a imputabilidade.", "explicacao": "CP, art. 28, II e § 1º (actio libera in causa para a voluntária)."}, {"id": 2000000026, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "Qual teoria do concurso de pessoas o CP adota como regra?", "verso": "Teoria monista (unitária): todos respondem pelo mesmo crime, na medida de sua culpabilidade.", "explicacao": "CP, art. 29. Há exceções pluralistas, como corrupção ativa e passiva."}, {"id": 2000000027, "trilha": "policial", "materia": "pen", "assunto": "Concurso de pessoas", "tipo": "pergunta", "frente": "Qual a redução para a participação de menor importância?", "verso": "De 1/6 a 1/3.", "explicacao": "CP, art. 29, § 1º."}, {"id": 2000000028, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais são as espécies de pena no CP?", "verso": "Privativas de liberdade, restritivas de direitos e multa.", "explicacao": "CP, art. 32."}, {"id": 2000000029, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Qual o tempo máximo de cumprimento das penas privativas de liberdade?", "verso": "40 anos.", "explicacao": "CP, art. 75, com redação do Pacote Anticrime (antes eram 30)."}, {"id": 2000000030, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Pena superior a 8 anos: qual o regime inicial?", "verso": "Fechado.", "explicacao": "CP, art. 33, § 2º, a. Mais de 4 até 8 (não reincidente): semiaberto; até 4 (não reincidente): aberto."}, {"id": 2000000031, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Quais os requisitos para substituir a prisão por pena restritiva de direitos?", "verso": "Pena não superior a 4 anos e crime sem violência ou grave ameaça (ou crime culposo, qualquer pena), réu não reincidente em crime doloso e circunstâncias judiciais favoráveis.", "explicacao": "CP, art. 44."}, {"id": 2000000032, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Depois de quanto tempo a condenação anterior deixa de gerar reincidência?", "verso": "5 anos, contados do cumprimento ou extinção da pena.", "explicacao": "CP, art. 64, I (período depurador)."}, {"id": 2000000033, "trilha": "policial", "materia": "pen", "assunto": "Penas", "tipo": "pergunta", "frente": "Que idades geram atenuante genérica?", "verso": "Menor de 21 anos na data do fato ou maior de 70 anos na data da sentença.", "explicacao": "CP, art. 65, I."}, {"id": 2000000034, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "lacuna", "frente": "Reduzem-se de ____ os prazos de prescrição quando o criminoso era menor de 21 anos na data do crime ou maior de 70 na data da sentença.", "verso": "metade", "explicacao": "CP, art. 115."}, {"id": 2000000035, "trilha": "policial", "materia": "pen", "assunto": "Prescrição", "tipo": "pergunta", "frente": "Quais crimes a Constituição declara imprescritíveis?", "verso": "Racismo e ação de grupos armados, civis ou militares, contra a ordem constitucional e o Estado Democrático.", "explicacao": "CF, art. 5º, XLII e XLIV."}, {"id": 2000000036, "trilha": "policial", "materia": "pen", "assunto": "Constituição penal", "tipo": "pergunta", "frente": "Quais crimes são inafiançáveis e insuscetíveis de graça ou anistia (CF, art. 5º, XLIII)?", "verso": "Tortura, tráfico de drogas, terrorismo e crimes hediondos (“3TH”).", "explicacao": "CF, art. 5º, XLIII."}, {"id": 2000000037, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Qual a pena do homicídio simples?", "verso": "Reclusão de 6 a 20 anos.", "explicacao": "CP, art. 121, caput."}, {"id": 2000000038, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Qual a pena do homicídio qualificado?", "verso": "Reclusão de 12 a 30 anos.", "explicacao": "CP, art. 121, § 2º. É crime hediondo."}, {"id": 2000000039, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Como o feminicídio está previsto hoje no Código Penal?", "verso": "Como crime autônomo (art. 121-A), com pena de reclusão de 20 a 40 anos.", "explicacao": "Lei 14.994/2024 (pacote antifeminicídio). Antes era qualificadora do homicídio."}, {"id": 2000000040, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "Quando o homicídio é privilegiado?", "verso": "Quando cometido por relevante valor social ou moral, ou sob domínio de violenta emoção logo em seguida a injusta provocação da vítima. Reduz a pena de 1/6 a 1/3.", "explicacao": "CP, art. 121, § 1º."}, {"id": 2000000041, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a vida", "tipo": "pergunta", "frente": "O que caracteriza o infanticídio?", "verso": "Matar o próprio filho, sob influência do estado puerperal, durante o parto ou logo após.", "explicacao": "CP, art. 123."}, {"id": 2000000042, "trilha": "policial", "materia": "pen", "assunto": "Lesão corporal", "tipo": "pares", "frente": "Diferencie lesão corporal grave de gravíssima (exemplos).", "verso": "Grave: incapacidade para ocupações habituais por mais de 30 dias, perigo de vida, debilidade permanente, aceleração de parto. Gravíssima: incapacidade permanente para o trabalho, enfermidade incurável, perda ou inutilização de membro, sentido ou função, deformidade permanente, aborto.", "explicacao": "CP, art. 129, §§ 1º e 2º. Debilidade = grave; perda = gravíssima."}, {"id": 2000000043, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a honra", "tipo": "pares", "frente": "Calúnia, difamação e injúria: qual a diferença?", "verso": "Calúnia: imputar falsamente fato definido como crime. Difamação: imputar fato ofensivo à reputação. Injúria: ofender a dignidade ou o decoro, sem imputar fato.", "explicacao": "CP, arts. 138, 139 e 140. Calúnia e difamação atingem a honra objetiva; injúria, a subjetiva."}, {"id": 2000000044, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do furto simples?", "verso": "Reclusão de 1 a 4 anos e multa.", "explicacao": "CP, art. 155, caput."}, {"id": 2000000045, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual o aumento do furto praticado durante o repouso noturno?", "verso": "Aumenta de 1/3.", "explicacao": "CP, art. 155, § 1º."}, {"id": 2000000046, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Quais os requisitos do furto privilegiado?", "verso": "Criminoso primário e coisa furtada de pequeno valor. O juiz pode trocar reclusão por detenção, reduzir de 1/3 a 2/3 ou aplicar só multa.", "explicacao": "CP, art. 155, § 2º."}, {"id": 2000000047, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Quais são as qualificadoras clássicas do furto (§ 4º)?", "verso": "Destruição ou rompimento de obstáculo; abuso de confiança, fraude, escalada ou destreza; chave falsa; concurso de duas ou mais pessoas.", "explicacao": "CP, art. 155, § 4º. Pena de 2 a 8 anos."}, {"id": 2000000048, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do roubo simples?", "verso": "Reclusão de 4 a 10 anos e multa.", "explicacao": "CP, art. 157, caput."}, {"id": 2000000049, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é roubo impróprio?", "verso": "Quando a violência ou grave ameaça é empregada logo depois de subtraída a coisa, para assegurar a impunidade ou a detenção da coisa.", "explicacao": "CP, art. 157, § 1º. No roubo próprio, a violência vem antes ou durante a subtração."}, {"id": 2000000050, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Roubo com arma de fogo: qual o aumento? E se a arma for de uso restrito ou proibido?", "verso": "Arma de fogo: aumenta 2/3. Arma de uso restrito ou proibido: aplica-se em dobro.", "explicacao": "CP, art. 157, § 2º-A, I, e § 2º-B."}, {"id": 2000000051, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual a pena do latrocínio e quem o julga?", "verso": "Reclusão de 20 a 30 anos. É julgado pelo juiz singular, não pelo júri.", "explicacao": "CP, art. 157, § 3º, II. Súmula 603 do STF: é crime contra o patrimônio."}, {"id": 2000000052, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre extorsão e roubo?", "verso": "Na extorsão, a vantagem depende de uma conduta da própria vítima (ela faz, tolera ou deixa de fazer algo). No roubo, o agente subtrai a coisa por si.", "explicacao": "CP, arts. 157 e 158."}, {"id": 2000000053, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Como se tipifica o “sequestro relâmpago”?", "verso": "Extorsão com restrição da liberdade da vítima, condição necessária para obter a vantagem.", "explicacao": "CP, art. 158, § 3º."}, {"id": 2000000054, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pares", "frente": "Qual a diferença entre apropriação indébita e furto?", "verso": "Na apropriação indébita, o agente já tem a posse ou detenção lícita da coisa e passa a agir como dono. No furto, ele subtrai coisa que não estava com ele.", "explicacao": "CP, arts. 155 e 168."}, {"id": 2000000055, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "Qual é, em regra, a ação penal no estelionato?", "verso": "Pública condicionada à representação.", "explicacao": "CP, art. 171, § 5º (Pacote Anticrime). É incondicionada se a vítima for a Administração Pública, criança ou adolescente, pessoa com deficiência mental, maior de 70 anos ou incapaz."}, {"id": 2000000056, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é escusa absolutória nos crimes patrimoniais?", "verso": "Isenção de pena para quem comete crime patrimonial sem violência ou grave ameaça contra cônjuge (na constância da sociedade conjugal), ascendente ou descendente.", "explicacao": "CP, art. 181. Não se aplica se a vítima tiver 60 anos ou mais (art. 183)."}, {"id": 2000000057, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra o patrimônio", "tipo": "pergunta", "frente": "O que é receptação?", "verso": "Adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime, ou influir para que terceiro de boa-fé a adquira.", "explicacao": "CP, art. 180."}, {"id": 2000000058, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a dignidade sexual", "tipo": "pergunta", "frente": "Até que idade a vítima é considerada vulnerável no art. 217-A do CP?", "verso": "Menor de 14 anos.", "explicacao": "CP, art. 217-A. O consentimento da vítima ou experiência anterior é irrelevante (§ 5º)."}, {"id": 2000000059, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é peculato (art. 312)?", "verso": "O funcionário público se apropriar de dinheiro, valor ou bem móvel de que tem a posse em razão do cargo, ou desviá-lo em proveito próprio ou alheio.", "explicacao": "CP, art. 312. Peculato-furto: subtrai valendo-se da facilidade do cargo (§ 1º)."}, {"id": 2000000060, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "No peculato culposo, qual o efeito da reparação do dano?", "verso": "Antes da sentença irrecorrível: extingue a punibilidade. Depois: reduz a pena pela metade.", "explicacao": "CP, art. 312, § 3º."}, {"id": 2000000061, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Concussão x corrupção passiva: qual o verbo de cada uma?", "verso": "Concussão: EXIGIR vantagem indevida. Corrupção passiva: SOLICITAR, RECEBER ou ACEITAR PROMESSA de vantagem.", "explicacao": "CP, arts. 316 e 317."}, {"id": 2000000062, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é prevaricação?", "verso": "Retardar ou deixar de praticar ato de ofício, ou praticá-lo contra disposição de lei, para satisfazer interesse ou sentimento pessoal.", "explicacao": "CP, art. 319."}, {"id": 2000000063, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "Quem é funcionário público para fins penais?", "verso": "Quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública.", "explicacao": "CP, art. 327. Equipara-se quem trabalha em entidade paraestatal ou empresa contratada para atividade típica (§ 1º)."}, {"id": 2000000064, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Resistência x desobediência: qual a diferença?", "verso": "Resistência: opor-se à execução de ato legal mediante violência ou ameaça ao funcionário. Desobediência: desobedecer ordem legal, sem violência.", "explicacao": "CP, arts. 329 e 330."}, {"id": 2000000065, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é denunciação caluniosa?", "verso": "Dar causa à instauração de investigação, processo ou ação contra alguém, imputando-lhe crime (ou infração) de que o sabe inocente.", "explicacao": "CP, art. 339. Não confundir com calúnia, que só ofende a honra."}, {"id": 2000000066, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "certo_errado", "frente": "Certo ou errado? O preso que foge sem usar violência contra a pessoa comete crime.", "verso": "Errado. A fuga sem violência não é crime, mas é falta grave na execução.", "explicacao": "CP, art. 352 (evasão exige violência) e LEP, art. 50, II."}, {"id": 2000000067, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pergunta", "frente": "O que é desacato?", "verso": "Desacatar funcionário público no exercício da função ou em razão dela.", "explicacao": "CP, art. 331. O STF considerou o tipo compatível com a Constituição (ADPF 496)."}, {"id": 2000000068, "trilha": "policial", "materia": "pen", "assunto": "Crimes contra a Administração", "tipo": "pares", "frente": "Corrupção ativa x corrupção passiva: quem pratica cada uma?", "verso": "Ativa: o particular que oferece ou promete vantagem indevida ao funcionário. Passiva: o funcionário que solicita, recebe ou aceita a promessa.", "explicacao": "CP, arts. 333 e 317. Exceção à teoria monista: cada um responde por um crime."}, {"id": 2000000069, "trilha": "policial", "materia": "pen", "assunto": "Extinção da punibilidade", "tipo": "pergunta", "frente": "Cite causas de extinção da punibilidade do art. 107 do CP.", "verso": "Morte do agente, anistia, graça ou indulto, abolitio criminis, prescrição, decadência ou perempção, renúncia ou perdão aceito (ação privada), retratação (quando a lei admite) e perdão judicial.", "explicacao": "CP, art. 107."}, {"id": 2000000070, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quais as características do inquérito policial?", "verso": "Procedimento administrativo, escrito, inquisitivo, sigiloso, oficioso, indisponível para a autoridade policial e dispensável para a ação penal.", "explicacao": "CPP, arts. 4º a 23."}, {"id": 2000000071, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quem preside o inquérito policial?", "verso": "O delegado de polícia.", "explicacao": "Lei 12.830/2013, art. 2º, § 1º."}, {"id": 2000000072, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pares", "frente": "Prazo do inquérito no CPP: indiciado preso x solto.", "verso": "Preso: 10 dias. Solto: 30 dias (prorrogável pelo juiz).", "explicacao": "CPP, art. 10."}, {"id": 2000000073, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Prazo do inquérito da Polícia Federal com indiciado preso:", "verso": "15 dias, prorrogáveis por mais 15.", "explicacao": "Lei 5.010/1966, art. 66."}, {"id": 2000000074, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pares", "frente": "Prazo do inquérito na Lei de Drogas: preso x solto.", "verso": "Preso: 30 dias. Solto: 90 dias. Os dois podem ser duplicados pelo juiz.", "explicacao": "Lei 11.343/2006, art. 51."}, {"id": 2000000075, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "certo_errado", "frente": "Certo ou errado? A autoridade policial pode mandar arquivar os autos de inquérito.", "verso": "Errado.", "explicacao": "CPP, art. 17."}, {"id": 2000000076, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Na ação penal privada, como se instaura o inquérito?", "verso": "Só a requerimento de quem tenha qualidade para propor a ação (o ofendido ou seu representante).", "explicacao": "CPP, art. 5º, § 5º. Na condicionada, depende de representação (§ 4º)."}, {"id": 2000000077, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O indiciamento é ato de quem?", "verso": "Privativo do delegado de polícia, por ato fundamentado, com análise técnico-jurídica do fato.", "explicacao": "Lei 12.830/2013, art. 2º, § 6º."}, {"id": 2000000078, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O que garante a Súmula Vinculante 14?", "verso": "Acesso amplo do defensor aos elementos de prova já documentados no procedimento investigatório, no interesse do representado.", "explicacao": "Súmula Vinculante 14 do STF. Diligências em andamento podem ficar sob sigilo."}, {"id": 2000000079, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "certo_errado", "frente": "Certo ou errado? A incomunicabilidade do indiciado por até 3 dias (CPP, art. 21) foi recepcionada pela Constituição.", "verso": "Errado. Prevalece que não foi recepcionada: a CF veda a incomunicabilidade até no estado de defesa.", "explicacao": "CF, art. 136, § 3º, IV."}, {"id": 2000000080, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O juiz pode condenar com base apenas no inquérito?", "verso": "Não. Não pode fundamentar a decisão exclusivamente nos elementos informativos da investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.", "explicacao": "CPP, art. 155."}, {"id": 2000000081, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Arquivado o inquérito a pedido do MP, pode-se depois iniciar a ação penal?", "verso": "Só com novas provas.", "explicacao": "Súmula 524 do STF e CPP, art. 18."}, {"id": 2000000082, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pares", "frente": "Flagrante próprio, impróprio e presumido: o que é cada um?", "verso": "Próprio: está cometendo ou acaba de cometer. Impróprio: é perseguido logo após, em situação que faça presumir a autoria. Presumido (ficto): é encontrado logo depois com instrumentos, armas, objetos ou papéis que façam presumir a autoria.", "explicacao": "CPP, art. 302."}, {"id": 2000000083, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pares", "frente": "Flagrante preparado x flagrante esperado: qual é válido?", "verso": "Preparado (provocado pela polícia): não há crime (Súmula 145 do STF). Esperado (a polícia só aguarda o crime acontecer): é válido.", "explicacao": "Súmula 145 do STF."}, {"id": 2000000084, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "O que é flagrante diferido ou retardado?", "verso": "A ação controlada: a polícia retarda a intervenção para agir no momento mais eficaz para a prova.", "explicacao": "Lei 12.850/2013, art. 8º, e Lei 11.343/2006, art. 53, II."}, {"id": 2000000085, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "Em quanto tempo o auto de prisão em flagrante vai ao juiz e a nota de culpa ao preso?", "verso": "Em até 24 horas.", "explicacao": "CPP, art. 306, §§ 1º e 2º. A prisão deve ser comunicada imediatamente ao juiz, ao MP e à família."}, {"id": 2000000086, "trilha": "policial", "materia": "ppen", "assunto": "Prisão em flagrante", "tipo": "pergunta", "frente": "Em que prazo deve ocorrer a audiência de custódia?", "verso": "Em até 24 horas após a prisão.", "explicacao": "CPP, art. 310."}, {"id": 2000000087, "trilha": "policial", "materia": "ppen", "assunto": "Fiança", "tipo": "pergunta", "frente": "Até que pena o delegado pode conceder fiança?", "verso": "Infrações cuja pena privativa de liberdade máxima não seja superior a 4 anos.", "explicacao": "CPP, art. 322. Acima disso, só o juiz."}, {"id": 2000000088, "trilha": "policial", "materia": "ppen", "assunto": "Fiança", "tipo": "pergunta", "frente": "Quais crimes são inafiançáveis pelo CPP?", "verso": "Racismo, tortura, tráfico de drogas, terrorismo, crimes hediondos e ação de grupos armados contra a ordem constitucional.", "explicacao": "CPP, art. 323."}, {"id": 2000000089, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "pergunta", "frente": "Quais os fundamentos da prisão preventiva?", "verso": "Garantia da ordem pública ou econômica, conveniência da instrução criminal ou assegurar a aplicação da lei penal, com prova do crime, indício suficiente de autoria e perigo gerado pela liberdade do imputado.", "explicacao": "CPP, art. 312."}, {"id": 2000000090, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "certo_errado", "frente": "Certo ou errado? Após o Pacote Anticrime, o juiz pode decretar a preventiva de ofício.", "verso": "Errado. Só a requerimento do MP, do querelante ou do assistente, ou por representação da autoridade policial.", "explicacao": "CPP, art. 311."}, {"id": 2000000091, "trilha": "policial", "materia": "ppen", "assunto": "Prisão preventiva", "tipo": "pergunta", "frente": "De quanto em quanto tempo a necessidade da preventiva deve ser revista?", "verso": "A cada 90 dias, por decisão fundamentada, de ofício.", "explicacao": "CPP, art. 316, parágrafo único."}, {"id": 2000000092, "trilha": "policial", "materia": "ppen", "assunto": "Prisão temporária", "tipo": "pares", "frente": "Prazo da prisão temporária: regra x crimes hediondos.", "verso": "Regra: 5 dias, prorrogáveis por mais 5. Hediondos e equiparados: 30 dias, prorrogáveis por mais 30.", "explicacao": "Lei 7.960/1989, art. 2º, e Lei 8.072/1990, art. 2º, § 4º."}, {"id": 2000000093, "trilha": "policial", "materia": "ppen", "assunto": "Prisão temporária", "tipo": "pergunta", "frente": "Em que fase cabe a prisão temporária?", "verso": "Apenas na investigação (inquérito policial).", "explicacao": "Lei 7.960/1989."}, {"id": 2000000094, "trilha": "policial", "materia": "ppen", "assunto": "Cautelares", "tipo": "pergunta", "frente": "Cite medidas cautelares diversas da prisão.", "verso": "Comparecimento periódico em juízo, proibição de frequentar lugares, proibição de contato, proibição de ausentar-se da comarca, recolhimento domiciliar noturno, suspensão da função pública, internação provisória, fiança e monitoração eletrônica.", "explicacao": "CPP, art. 319."}, {"id": 2000000095, "trilha": "policial", "materia": "ppen", "assunto": "Cautelares", "tipo": "pergunta", "frente": "Em que casos o juiz pode substituir a preventiva por prisão domiciliar?", "verso": "Maior de 80 anos, extremamente debilitado por doença grave, imprescindível aos cuidados de menor de 6 anos ou pessoa com deficiência, gestante, mulher com filho de até 12 anos incompletos ou homem único responsável por filho dessa idade.", "explicacao": "CPP, art. 318."}, {"id": 2000000096, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Quem é o titular da ação penal pública?", "verso": "O Ministério Público.", "explicacao": "CF, art. 129, I."}, {"id": 2000000097, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Prazo para o MP oferecer a denúncia: réu preso x solto.", "verso": "Preso: 5 dias. Solto: 15 dias.", "explicacao": "CPP, art. 46."}, {"id": 2000000098, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Qual o prazo decadencial para queixa ou representação?", "verso": "6 meses, contados do dia em que o ofendido souber quem é o autor do crime.", "explicacao": "CPP, art. 38, e CP, art. 103."}, {"id": 2000000099, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pergunta", "frente": "Quando cabe ação penal privada subsidiária da pública?", "verso": "Quando o MP não oferece a denúncia no prazo legal (inércia).", "explicacao": "CF, art. 5º, LIX, e CPP, art. 29. Não cabe se o MP pediu arquivamento."}, {"id": 2000000100, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Princípios da ação pública x ação privada.", "verso": "Pública: obrigatoriedade e indisponibilidade. Privada: oportunidade (conveniência) e disponibilidade. As duas são indivisíveis.", "explicacao": "Na privada, a renúncia em relação a um autor se estende a todos (CPP, art. 49)."}, {"id": 2000000101, "trilha": "policial", "materia": "ppen", "assunto": "Ação penal", "tipo": "pares", "frente": "Renúncia x perdão do ofendido.", "verso": "Renúncia: antes da queixa e unilateral. Perdão: depois de iniciada a ação e bilateral (precisa ser aceito).", "explicacao": "CP, arts. 104 a 106."}, {"id": 2000000102, "trilha": "policial", "materia": "ppen", "assunto": "Competência", "tipo": "pergunta", "frente": "Qual a regra geral de competência territorial no CPP?", "verso": "O lugar em que se consumou a infração; na tentativa, o lugar do último ato de execução.", "explicacao": "CPP, art. 70 (teoria do resultado)."}, {"id": 2000000103, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Qual a competência constitucional do Tribunal do Júri?", "verso": "Julgar os crimes dolosos contra a vida, tentados ou consumados, e os conexos.", "explicacao": "CF, art. 5º, XXXVIII, d."}, {"id": 2000000104, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quais os princípios constitucionais do júri?", "verso": "Plenitude de defesa, sigilo das votações, soberania dos veredictos e competência para os crimes dolosos contra a vida.", "explicacao": "CF, art. 5º, XXXVIII."}, {"id": 2000000105, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pergunta", "frente": "Quais as quatro decisões possíveis ao fim da primeira fase do júri?", "verso": "Pronúncia, impronúncia, desclassificação e absolvição sumária.", "explicacao": "CPP, arts. 413 a 419."}, {"id": 2000000106, "trilha": "policial", "materia": "ppen", "assunto": "Júri", "tipo": "pares", "frente": "Recurso cabível: contra pronúncia x contra impronúncia ou absolvição sumária.", "verso": "Pronúncia: recurso em sentido estrito. Impronúncia e absolvição sumária: apelação.", "explicacao": "CPP, arts. 581, IV, e 416."}, {"id": 2000000107, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Qual o prazo da apelação e do recurso em sentido estrito?", "verso": "5 dias para interpor.", "explicacao": "CPP, arts. 593 e 586."}, {"id": 2000000108, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "certo_errado", "frente": "Certo ou errado? Em recurso exclusivo da defesa, o tribunal pode piorar a situação do réu.", "verso": "Errado. É vedada a reformatio in pejus.", "explicacao": "CPP, art. 617."}, {"id": 2000000109, "trilha": "policial", "materia": "ppen", "assunto": "Recursos", "tipo": "pergunta", "frente": "Quando cabe revisão criminal?", "verso": "A qualquer tempo, antes ou depois de extinta a pena, e só em favor do réu.", "explicacao": "CPP, arts. 621 e 622."}, {"id": 2000000110, "trilha": "policial", "materia": "ppen", "assunto": "Habeas corpus", "tipo": "pergunta", "frente": "Quando cabe habeas corpus?", "verso": "Sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder.", "explicacao": "CF, art. 5º, LXVIII."}, {"id": 2000000111, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "O que acontece com a prova ilícita e a derivada dela?", "verso": "São inadmissíveis e devem ser desentranhadas, salvo quando não houver nexo de causalidade ou a derivada puder ser obtida por fonte independente.", "explicacao": "CF, art. 5º, LVI, e CPP, art. 157 (frutos da árvore envenenada)."}, {"id": 2000000112, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "O que é cadeia de custódia?", "verso": "O conjunto de procedimentos para manter e documentar a história cronológica do vestígio, do reconhecimento ao descarte.", "explicacao": "CPP, art. 158-A (Pacote Anticrime)."}, {"id": 2000000113, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "certo_errado", "frente": "Certo ou errado? Quando a infração deixa vestígios, a confissão pode suprir o exame de corpo de delito.", "verso": "Errado. O exame é indispensável e a confissão não o supre.", "explicacao": "CPP, art. 158. Se os vestígios desaparecerem, a prova testemunhal pode supri-lo (art. 167)."}, {"id": 2000000114, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quantos peritos fazem o exame de corpo de delito?", "verso": "Um perito oficial com diploma de curso superior. Na falta, duas pessoas idôneas com diploma superior.", "explicacao": "CPP, art. 159."}, {"id": 2000000115, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quando se pode entrar numa casa durante a noite sem consentimento?", "verso": "Em flagrante delito, desastre ou para prestar socorro. Por ordem judicial, só durante o dia.", "explicacao": "CF, art. 5º, XI."}, {"id": 2000000116, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Requisitos da interceptação telefônica.", "verso": "Ordem judicial, indícios razoáveis de autoria, crime punido com reclusão e impossibilidade de obter a prova por outros meios. Prazo de 15 dias, renovável.", "explicacao": "Lei 9.296/1996, arts. 2º e 5º."}, {"id": 2000000117, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Como deve ser feito o reconhecimento de pessoas?", "verso": "A testemunha descreve a pessoa; o suspeito é colocado ao lado de outras parecidas; lavra-se auto pormenorizado.", "explicacao": "CPP, art. 226. O STJ considera essas formalidades garantia mínima do suspeito."}, {"id": 2000000118, "trilha": "policial", "materia": "ppen", "assunto": "Provas", "tipo": "pergunta", "frente": "Quais as características da confissão no CPP?", "verso": "É retratável e divisível, e vale em conjunto com as demais provas.", "explicacao": "CPP, arts. 197 e 200."}, {"id": 2000000119, "trilha": "policial", "materia": "ppen", "assunto": "Interrogatório", "tipo": "certo_errado", "frente": "Certo ou errado? O silêncio do acusado pode ser interpretado em prejuízo da defesa.", "verso": "Errado.", "explicacao": "CF, art. 5º, LXIII, e CPP, art. 186, parágrafo único."}, {"id": 2000000120, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "No procedimento comum, em que momento ocorre o interrogatório?", "verso": "É o último ato da instrução.", "explicacao": "CPP, art. 400."}, {"id": 2000000121, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pares", "frente": "Procedimento ordinário x sumário x sumaríssimo: critério.", "verso": "Ordinário: pena máxima igual ou superior a 4 anos. Sumário: inferior a 4 anos. Sumaríssimo: infrações de menor potencial ofensivo.", "explicacao": "CPP, art. 394, § 1º."}, {"id": 2000000122, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pares", "frente": "Número de testemunhas: ordinário x sumário.", "verso": "Ordinário: até 8 por parte. Sumário: até 5.", "explicacao": "CPP, arts. 401 e 532."}, {"id": 2000000123, "trilha": "policial", "materia": "ppen", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Acusado citado por edital não comparece nem constitui advogado. E agora?", "verso": "Ficam suspensos o processo e o curso do prazo prescricional.", "explicacao": "CPP, art. 366."}, {"id": 2000000124, "trilha": "policial", "materia": "ppen", "assunto": "Sentença", "tipo": "pares", "frente": "Emendatio libelli x mutatio libelli.", "verso": "Emendatio: o juiz dá nova definição jurídica ao mesmo fato descrito. Mutatio: surge prova de elemento ou circunstância não descrita, e o MP deve aditar a denúncia.", "explicacao": "CPP, arts. 383 e 384."}, {"id": 2000000125, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "O que é infração de menor potencial ofensivo?", "verso": "Contravenções penais e crimes com pena máxima não superior a 2 anos.", "explicacao": "Lei 9.099/1995, art. 61."}, {"id": 2000000126, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Requisito de pena para a suspensão condicional do processo:", "verso": "Pena mínima cominada igual ou inferior a 1 ano. Período de prova de 2 a 4 anos.", "explicacao": "Lei 9.099/1995, art. 89."}, {"id": 2000000127, "trilha": "policial", "materia": "ppen", "assunto": "Juizados", "tipo": "pergunta", "frente": "Nas infrações de menor potencial ofensivo, o que a polícia lavra em vez do auto de prisão?", "verso": "O termo circunstanciado. Não se impõe prisão em flagrante se o autor se comprometer a comparecer ao juizado.", "explicacao": "Lei 9.099/1995, art. 69."}, {"id": 2000000128, "trilha": "policial", "materia": "ppen", "assunto": "ANPP", "tipo": "pergunta", "frente": "Requisitos do acordo de não persecução penal.", "verso": "Infração sem violência ou grave ameaça, pena mínima inferior a 4 anos e confissão formal e circunstanciada, sendo suficiente para reprovação e prevenção do crime.", "explicacao": "CPP, art. 28-A."}, {"id": 2000000129, "trilha": "policial", "materia": "ppen", "assunto": "Juiz das garantias", "tipo": "pergunta", "frente": "Qual a função do juiz das garantias?", "verso": "Controlar a legalidade da investigação criminal e salvaguardar os direitos individuais do investigado.", "explicacao": "CPP, art. 3º-B, considerado constitucional pelo STF (ADIs 6.298 e outras)."}, {"id": 2000000130, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Qual a natureza da colaboração premiada?", "verso": "Negócio jurídico processual e meio de obtenção de prova.", "explicacao": "Lei 12.850/2013, art. 3º-A."}, {"id": 2000000131, "trilha": "policial", "materia": "ppen", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "A infiltração de agentes depende de quê? Qual o prazo?", "verso": "De autorização judicial circunstanciada. Prazo de até 6 meses, renovável.", "explicacao": "Lei 12.850/2013, art. 10."}, {"id": 2000000132, "trilha": "policial", "materia": "ppen", "assunto": "Algemas", "tipo": "pergunta", "frente": "Quando o uso de algemas é lícito (Súmula Vinculante 11)?", "verso": "Em caso de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, justificado por escrito.", "explicacao": "Súmula Vinculante 11 do STF."}, {"id": 2000000133, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "Quais são as formas de notitia criminis?", "verso": "De cognição imediata (a polícia sabe por suas atividades), mediata (por comunicação formal) e coercitiva (prisão em flagrante).", "explicacao": "Doutrina sobre o início do inquérito."}, {"id": 2000000134, "trilha": "policial", "materia": "ppen", "assunto": "Inquérito policial", "tipo": "pergunta", "frente": "O sigilo do inquérito existe para quê?", "verso": "Para a elucidação do fato ou por exigência do interesse da sociedade.", "explicacao": "CPP, art. 20."}, {"id": 2000000135, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Quais são os fundamentos da República (art. 1º)?", "verso": "Soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político.", "explicacao": "CF, art. 1º. Mnemônico SOCIDIVAPLU."}, {"id": 2000000136, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pergunta", "frente": "Quais são os Poderes da União?", "verso": "Legislativo, Executivo e Judiciário, independentes e harmônicos entre si.", "explicacao": "CF, art. 2º."}, {"id": 2000000137, "trilha": "policial", "materia": "const", "assunto": "Princípios fundamentais", "tipo": "pares", "frente": "Fundamentos (art. 1º) x objetivos (art. 3º): como diferenciar?", "verso": "Fundamentos são substantivos (soberania, cidadania…). Objetivos começam com verbos: construir, garantir, erradicar, promover.", "explicacao": "CF, arts. 1º e 3º."}, {"id": 2000000138, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A quem o caput do art. 5º garante os direitos fundamentais?", "verso": "Aos brasileiros e aos estrangeiros residentes no País (o STF estende aos não residentes).", "explicacao": "CF, art. 5º, caput."}, {"id": 2000000139, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "lacuna", "frente": "“A casa é asilo ____ do indivíduo, ninguém nela podendo penetrar sem consentimento do morador…”", "verso": "inviolável", "explicacao": "CF, art. 5º, XI."}, {"id": 2000000140, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quais as exceções à inviolabilidade do sigilo das comunicações telefônicas?", "verso": "Por ordem judicial, nas hipóteses e forma que a lei estabelecer, para investigação criminal ou instrução processual penal.", "explicacao": "CF, art. 5º, XII, e Lei 9.296/1996."}, {"id": 2000000141, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Em que hipóteses alguém pode ser preso?", "verso": "Em flagrante delito ou por ordem escrita e fundamentada de autoridade judiciária competente (salvo transgressão militar e crime propriamente militar).", "explicacao": "CF, art. 5º, LXI."}, {"id": 2000000142, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que direitos o preso tem no momento da prisão?", "verso": "Ser informado de seus direitos, inclusive o de permanecer calado; assistência da família e de advogado; identificação dos responsáveis pela prisão.", "explicacao": "CF, art. 5º, LXIII e LXIV."}, {"id": 2000000143, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Que prisão civil por dívida a Constituição admite e qual o STF aceita hoje?", "verso": "A CF prevê a do devedor de alimentos e a do depositário infiel, mas só a do devedor voluntário e inescusável de alimentos é admitida.", "explicacao": "CF, art. 5º, LXVII, e Súmula Vinculante 25."}, {"id": 2000000144, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? No Brasil pode haver pena de morte em caso de guerra declarada.", "verso": "Certo. É a única exceção.", "explicacao": "CF, art. 5º, XLVII, a."}, {"id": 2000000145, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Quais penas a Constituição proíbe?", "verso": "De morte (salvo guerra declarada), de caráter perpétuo, de trabalhos forçados, de banimento e cruéis.", "explicacao": "CF, art. 5º, XLVII."}, {"id": 2000000146, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? O brasileiro nato pode ser extraditado se comprovado envolvimento em tráfico de drogas.", "verso": "Errado. O brasileiro nato nunca é extraditado. O naturalizado pode ser, por crime comum antes da naturalização ou por tráfico de drogas.", "explicacao": "CF, art. 5º, LI."}, {"id": 2000000147, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "certo_errado", "frente": "Certo ou errado? A reunião pacífica em local aberto depende de autorização prévia.", "verso": "Errado. Basta aviso prévio à autoridade competente.", "explicacao": "CF, art. 5º, XVI."}, {"id": 2000000148, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Associação pode ser dissolvida compulsoriamente por quê?", "verso": "Só por decisão judicial transitada em julgado. Para suspender atividades, basta decisão judicial.", "explicacao": "CF, art. 5º, XIX."}, {"id": 2000000149, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "A lei pode retroagir para prejudicar o quê?", "verso": "Não pode prejudicar o direito adquirido, o ato jurídico perfeito e a coisa julgada.", "explicacao": "CF, art. 5º, XXXVI."}, {"id": 2000000150, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pares", "frente": "Habeas corpus x habeas data.", "verso": "Habeas corpus: protege a liberdade de locomoção. Habeas data: garante conhecer ou retificar informações pessoais em bancos de dados públicos.", "explicacao": "CF, art. 5º, LXVIII e LXXII."}, {"id": 2000000151, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pares", "frente": "Mandado de segurança x mandado de injunção.", "verso": "Segurança: protege direito líquido e certo não amparado por HC ou HD. Injunção: quando falta norma regulamentadora que torna inviável o exercício de um direito.", "explicacao": "CF, art. 5º, LXIX e LXXI."}, {"id": 2000000152, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pergunta", "frente": "Quem pode propor ação popular?", "verso": "Qualquer cidadão (eleitor).", "explicacao": "CF, art. 5º, LXXIII. Isento de custas, salvo má-fé."}, {"id": 2000000153, "trilha": "policial", "materia": "const", "assunto": "Remédios constitucionais", "tipo": "pergunta", "frente": "Quais ações são gratuitas por força da Constituição?", "verso": "Habeas corpus e habeas data e, na forma da lei, os atos necessários ao exercício da cidadania.", "explicacao": "CF, art. 5º, LXXVII."}, {"id": 2000000154, "trilha": "policial", "materia": "const", "assunto": "Direitos fundamentais", "tipo": "pergunta", "frente": "Tratados de direitos humanos aprovados com rito de emenda têm que status?", "verso": "Equivalem a emendas constitucionais: 3/5 dos votos, em dois turnos, em cada Casa.", "explicacao": "CF, art. 5º, § 3º."}, {"id": 2000000155, "trilha": "policial", "materia": "const", "assunto": "Nacionalidade", "tipo": "pergunta", "frente": "Quais cargos são privativos de brasileiro nato?", "verso": "Presidente e Vice; Presidentes da Câmara e do Senado; Ministro do STF; carreira diplomática; oficial das Forças Armadas; Ministro de Estado da Defesa.", "explicacao": "CF, art. 12, § 3º. Mnemônico MP3.COM."}, {"id": 2000000156, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Quem é obrigado e quem é facultado a votar?", "verso": "Obrigatório: maiores de 18 anos. Facultativo: analfabetos, maiores de 70 e quem tem entre 16 e 18 anos.", "explicacao": "CF, art. 14, § 1º."}, {"id": 2000000157, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "pergunta", "frente": "Qual a idade mínima para Presidente e para Senador?", "verso": "35 anos.", "explicacao": "CF, art. 14, § 3º, VI, a. Governador: 30; Deputado e Prefeito: 21; Vereador: 18."}, {"id": 2000000158, "trilha": "policial", "materia": "const", "assunto": "Direitos políticos", "tipo": "certo_errado", "frente": "Certo ou errado? A Constituição admite a cassação de direitos políticos.", "verso": "Errado. É vedada a cassação. Admite-se perda ou suspensão nos casos do art. 15.", "explicacao": "CF, art. 15."}, {"id": 2000000159, "trilha": "policial", "materia": "const", "assunto": "Organização do Estado", "tipo": "pergunta", "frente": "Quais são os entes da Federação?", "verso": "União, Estados, Distrito Federal e Municípios, todos autônomos.", "explicacao": "CF, art. 18. Territórios não são entes federativos."}, {"id": 2000000160, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Quais os princípios expressos da Administração Pública?", "verso": "Legalidade, impessoalidade, moralidade, publicidade e eficiência.", "explicacao": "CF, art. 37, caput. Mnemônico LIMPE."}, {"id": 2000000161, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual o prazo de validade do concurso público?", "verso": "Até 2 anos, prorrogável uma vez por igual período.", "explicacao": "CF, art. 37, III."}, {"id": 2000000162, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "O servidor efetivo adquire estabilidade após quanto tempo?", "verso": "3 anos de efetivo exercício, com avaliação especial de desempenho.", "explicacao": "CF, art. 41."}, {"id": 2000000163, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "O servidor estável pode perder o cargo em que casos?", "verso": "Sentença judicial transitada em julgado, processo administrativo com ampla defesa, avaliação periódica de desempenho insuficiente ou excesso de despesa com pessoal.", "explicacao": "CF, arts. 41, § 1º, e 169, § 4º."}, {"id": 2000000164, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "pergunta", "frente": "Qual a regra de responsabilidade civil do Estado?", "verso": "Objetiva: as pessoas jurídicas de direito público e as privadas prestadoras de serviço público respondem pelos danos que seus agentes causarem, com direito de regresso em caso de dolo ou culpa.", "explicacao": "CF, art. 37, § 6º."}, {"id": 2000000165, "trilha": "policial", "materia": "const", "assunto": "Administração Pública", "tipo": "certo_errado", "frente": "Certo ou errado? A Constituição permite acumular dois cargos de professor, se houver compatibilidade de horários.", "verso": "Certo.", "explicacao": "CF, art. 37, XVI. Também: professor + técnico/científico; dois cargos privativos de profissionais de saúde."}, {"id": 2000000166, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "lacuna", "frente": "“A segurança pública, dever do Estado, direito e ____ de todos, é exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio.”", "verso": "responsabilidade", "explicacao": "CF, art. 144, caput."}, {"id": 2000000167, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Quais órgãos estão listados no art. 144 da Constituição?", "verso": "Polícia Federal, Polícia Rodoviária Federal, Polícia Ferroviária Federal, polícias civis, polícias militares e corpos de bombeiros militares, e polícias penais federal, estaduais e distrital.", "explicacao": "CF, art. 144, I a VI (polícias penais incluídas pela EC 104/2019)."}, {"id": 2000000168, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias civis?", "verso": "Funções de polícia judiciária e apuração de infrações penais, exceto as militares, ressalvada a competência da União.", "explicacao": "CF, art. 144, § 4º. São dirigidas por delegados de polícia de carreira."}, {"id": 2000000169, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias militares?", "verso": "Polícia ostensiva e preservação da ordem pública.", "explicacao": "CF, art. 144, § 5º."}, {"id": 2000000170, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "A quem se subordinam as polícias militares e civis?", "verso": "Aos Governadores dos Estados, do DF e dos Territórios.", "explicacao": "CF, art. 144, § 6º. PM e bombeiros são forças auxiliares e reserva do Exército."}, {"id": 2000000171, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Cite atribuições da Polícia Federal.", "verso": "Apurar infrações contra a União e com repercussão interestadual ou internacional; prevenir e reprimir tráfico de drogas, contrabando e descaminho; polícia marítima, aeroportuária e de fronteiras; polícia judiciária da União com exclusividade.", "explicacao": "CF, art. 144, § 1º."}, {"id": 2000000172, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função da Polícia Rodoviária Federal?", "verso": "Patrulhamento ostensivo das rodovias federais.", "explicacao": "CF, art. 144, § 2º."}, {"id": 2000000173, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que os Municípios podem constituir na área de segurança?", "verso": "Guardas municipais destinadas à proteção de seus bens, serviços e instalações.", "explicacao": "CF, art. 144, § 8º. O STF reconhece as guardas como integrantes do sistema de segurança pública."}, {"id": 2000000174, "trilha": "policial", "materia": "const", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "Qual a função das polícias penais?", "verso": "A segurança dos estabelecimentos penais.", "explicacao": "CF, art. 144, § 5º-A (EC 104/2019)."}, {"id": 2000000175, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pares", "frente": "Estado de defesa x estado de sítio: quem autoriza?", "verso": "Estado de defesa: decretado pelo Presidente e submetido ao Congresso em 24 horas. Estado de sítio: depende de autorização prévia do Congresso.", "explicacao": "CF, arts. 136 e 137."}, {"id": 2000000176, "trilha": "policial", "materia": "const", "assunto": "Defesa do Estado", "tipo": "pergunta", "frente": "Qual a duração do estado de defesa?", "verso": "Até 30 dias, prorrogável uma vez por igual período.", "explicacao": "CF, art. 136, § 2º."}, {"id": 2000000177, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quantos senadores cada Estado elege e por quanto tempo?", "verso": "Três senadores, com mandato de 8 anos, renovando-se a representação de 4 em 4 anos, alternadamente, por 1/3 e 2/3.", "explicacao": "CF, art. 46."}, {"id": 2000000178, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quem tem iniciativa para propor emenda à Constituição?", "verso": "1/3 da Câmara ou do Senado, o Presidente da República ou mais da metade das Assembleias Legislativas (cada uma por maioria relativa).", "explicacao": "CF, art. 60."}, {"id": 2000000179, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Qual o quórum de aprovação de emenda constitucional?", "verso": "3/5 dos votos, em dois turnos, em cada Casa do Congresso.", "explicacao": "CF, art. 60, § 2º."}, {"id": 2000000180, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais são as cláusulas pétreas?", "verso": "Forma federativa de Estado; voto direto, secreto, universal e periódico; separação dos Poderes; direitos e garantias individuais.", "explicacao": "CF, art. 60, § 4º. Mnemônico FO.VO.SE.DI."}, {"id": 2000000181, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Quais poderes as CPIs têm?", "verso": "Poderes de investigação próprios das autoridades judiciais. As conclusões vão ao MP para promover a responsabilidade.", "explicacao": "CF, art. 58, § 3º. CPI não pode decretar prisão (salvo flagrante) nem interceptação telefônica."}, {"id": 2000000182, "trilha": "policial", "materia": "const", "assunto": "Poder Legislativo", "tipo": "pergunta", "frente": "Qual o quórum para aprovar lei complementar?", "verso": "Maioria absoluta.", "explicacao": "CF, art. 69. Lei ordinária: maioria simples."}, {"id": 2000000183, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Medida provisória: prazo de vigência.", "verso": "60 dias, prorrogável uma vez por mais 60. O prazo não corre no recesso.", "explicacao": "CF, art. 62, §§ 3º e 4º."}, {"id": 2000000184, "trilha": "policial", "materia": "const", "assunto": "Poder Executivo", "tipo": "pergunta", "frente": "Medida provisória pode tratar de direito penal?", "verso": "Não.", "explicacao": "CF, art. 62, § 1º, I, b. Também é vedada sobre processo penal, nacionalidade e direitos políticos, entre outros temas."}, {"id": 2000000185, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quantos ministros tem o STF e como são nomeados?", "verso": "11 ministros, brasileiros natos, com mais de 35 e menos de 70 anos, nomeados pelo Presidente após aprovação pela maioria absoluta do Senado.", "explicacao": "CF, art. 101."}, {"id": 2000000186, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Quais as garantias dos juízes?", "verso": "Vitaliciedade, inamovibilidade e irredutibilidade de subsídio.", "explicacao": "CF, art. 95."}, {"id": 2000000187, "trilha": "policial", "materia": "const", "assunto": "Poder Judiciário", "tipo": "pergunta", "frente": "Qual o efeito da súmula vinculante?", "verso": "Vincula os demais órgãos do Judiciário e a administração pública direta e indireta, em todas as esferas.", "explicacao": "CF, art. 103-A. Aprovada por 2/3 dos membros do STF."}, {"id": 2000000188, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "Quais as garantias dos membros do Ministério Público?", "verso": "Vitaliciedade, inamovibilidade e irredutibilidade de subsídio.", "explicacao": "CF, art. 128, § 5º, I."}, {"id": 2000000189, "trilha": "policial", "materia": "const", "assunto": "Funções essenciais", "tipo": "pergunta", "frente": "O que a Constituição atribui ao MP sobre a atividade policial?", "verso": "O controle externo da atividade policial.", "explicacao": "CF, art. 129, VII."}, {"id": 2000000190, "trilha": "policial", "materia": "const", "assunto": "Direitos sociais", "tipo": "pergunta", "frente": "Quais são os direitos sociais do art. 6º?", "verso": "Educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância e assistência aos desamparados.", "explicacao": "CF, art. 6º."}, {"id": 2000000191, "trilha": "policial", "materia": "const", "assunto": "Ordem social", "tipo": "pergunta", "frente": "Qual o dever da família, da sociedade e do Estado com a criança e o adolescente?", "verso": "Assegurar, com absoluta prioridade, seus direitos fundamentais, e colocá-los a salvo de negligência, discriminação, exploração, violência, crueldade e opressão.", "explicacao": "CF, art. 227."}, {"id": 2000000192, "trilha": "policial", "materia": "const", "assunto": "Ordem social", "tipo": "pergunta", "frente": "Qual a idade da inimputabilidade penal na Constituição?", "verso": "Menores de 18 anos são penalmente inimputáveis, sujeitos à legislação especial.", "explicacao": "CF, art. 228."}, {"id": 2000000193, "trilha": "policial", "materia": "const", "assunto": "Militares", "tipo": "pergunta", "frente": "Os militares podem se sindicalizar ou fazer greve?", "verso": "Não. São proibidas a sindicalização e a greve.", "explicacao": "CF, art. 142, § 3º, IV (aplicável aos militares dos Estados pelo art. 42, § 1º)."}, {"id": 2000000194, "trilha": "policial", "materia": "const", "assunto": "Militares", "tipo": "pergunta", "frente": "Cabe habeas corpus contra punição disciplinar militar?", "verso": "Não cabe quanto ao mérito da punição, mas cabe para discutir sua legalidade (pressupostos formais).", "explicacao": "CF, art. 142, § 2º, e jurisprudência do STF."}, {"id": 2000000195, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pares", "frente": "Porte para consumo (art. 28) x tráfico (art. 33): como o juiz diferencia?", "verso": "Pela natureza e quantidade da substância, local e condições da ação, circunstâncias sociais e pessoais, conduta e antecedentes do agente.", "explicacao": "Lei 11.343/2006, art. 28, § 2º."}, {"id": 2000000196, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais as penas para o porte de droga para consumo pessoal?", "verso": "Advertência sobre os efeitos das drogas, prestação de serviços à comunidade e medida educativa de comparecimento a programa ou curso. Não há pena de prisão.", "explicacao": "Lei 11.343/2006, art. 28. O STF (RE 635.659) fixou 40 g ou 6 plantas fêmeas como presunção relativa de uso, para a maconha."}, {"id": 2000000197, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Qual a pena do tráfico de drogas (art. 33)?", "verso": "Reclusão de 5 a 15 anos e multa.", "explicacao": "Lei 11.343/2006, art. 33, caput."}, {"id": 2000000198, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais os requisitos do tráfico privilegiado?", "verso": "Agente primário, de bons antecedentes, que não se dedique a atividades criminosas nem integre organização criminosa. Reduz a pena de 1/6 a 2/3.", "explicacao": "Lei 11.343/2006, art. 33, § 4º. O STF entende que não é hediondo."}, {"id": 2000000199, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Associação para o tráfico exige quantas pessoas?", "verso": "Duas ou mais, associadas de forma estável e permanente.", "explicacao": "Lei 11.343/2006, art. 35. Pena de 3 a 10 anos."}, {"id": 2000000200, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Oferecer droga, eventualmente e sem lucro, a pessoa do seu relacionamento, para consumirem juntos, é crime?", "verso": "Sim, crime de menor potencial ofensivo: detenção de 6 meses a 1 ano e multa, sem prejuízo das penas do art. 28.", "explicacao": "Lei 11.343/2006, art. 33, § 3º."}, {"id": 2000000201, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quais causas aumentam a pena do tráfico em 1/6 a 2/3?", "verso": "Transnacionalidade, interestadualidade, prevalecer-se de função pública, proximidade de escolas, hospitais, presídios e locais de trabalho coletivo, uso de violência ou arma, envolver criança ou adolescente, financiar o tráfico.", "explicacao": "Lei 11.343/2006, art. 40."}, {"id": 2000000202, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Quais as formas de violência doméstica e familiar contra a mulher?", "verso": "Física, psicológica, sexual, patrimonial e moral.", "explicacao": "Lei 11.340/2006, art. 7º."}, {"id": 2000000203, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? Nos crimes da Lei Maria da Penha, é possível aplicar os institutos da Lei 9.099 (transação, suspensão do processo).", "verso": "Errado.", "explicacao": "Lei 11.340/2006, art. 41, e Súmula 536 do STJ."}, {"id": 2000000204, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Qual a ação penal na lesão corporal contra a mulher em violência doméstica?", "verso": "Pública incondicionada.", "explicacao": "Súmula 542 do STJ e ADI 4.424 do STF."}, {"id": 2000000205, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? A autoridade policial pode conceder medida protetiva de afastamento do lar.", "verso": "Certo, em situação de risco atual ou iminente: o delegado, quando o município não for sede de comarca, ou o policial, quando também não houver delegado disponível. O juiz é comunicado em 24 horas.", "explicacao": "Lei 11.340/2006, art. 12-C."}, {"id": 2000000206, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Descumprir medida protetiva de urgência é crime?", "verso": "Sim: reclusão de 2 a 5 anos e multa. Só o juiz pode conceder fiança.", "explicacao": "Lei 11.340/2006, art. 24-A (redação da Lei 14.994/2024)."}, {"id": 2000000207, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "certo_errado", "frente": "Certo ou errado? A Lei Maria da Penha só protege a mulher que mora com o agressor.", "verso": "Errado. Aplica-se a qualquer relação íntima de afeto, independentemente de coabitação.", "explicacao": "Lei 11.340/2006, art. 5º, III, e Súmula 600 do STJ."}, {"id": 2000000208, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "Nos crimes de violência doméstica contra a mulher, cabe pena só de cesta básica ou multa?", "verso": "Não. É vedada a pena de cesta básica, prestação pecuniária ou substituição que implique pagamento isolado de multa.", "explicacao": "Lei 11.340/2006, art. 17."}, {"id": 2000000209, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pares", "frente": "Criança x adolescente no ECA.", "verso": "Criança: até 12 anos incompletos. Adolescente: de 12 a 18 anos.", "explicacao": "Lei 8.069/1990, art. 2º."}, {"id": 2000000210, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pares", "frente": "Ato infracional de criança x de adolescente: o que se aplica?", "verso": "Criança: medidas de proteção (art. 101). Adolescente: medidas socioeducativas (art. 112).", "explicacao": "ECA, arts. 105 e 112."}, {"id": 2000000211, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Qual o prazo máximo da internação do adolescente?", "verso": "3 anos, com reavaliação no máximo a cada 6 meses. Liberação compulsória aos 21 anos.", "explicacao": "ECA, art. 121, §§ 2º, 3º e 5º."}, {"id": 2000000212, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Prazo máximo da internação provisória (antes da sentença):", "verso": "45 dias.", "explicacao": "ECA, arts. 108 e 183."}, {"id": 2000000213, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Quais as medidas socioeducativas?", "verso": "Advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida, semiliberdade e internação.", "explicacao": "ECA, art. 112."}, {"id": 2000000214, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Corrupção de menores: o que diz a Súmula 500 do STJ?", "verso": "É crime formal: basta a participação do menor no crime, sem prova de que ele foi efetivamente corrompido.", "explicacao": "ECA, art. 244-B, e Súmula 500 do STJ."}, {"id": 2000000215, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "O adolescente apreendido em flagrante deve ser conduzido a quem?", "verso": "À autoridade policial competente; a apreensão e o local devem ser comunicados imediatamente ao juiz e à família.", "explicacao": "ECA, arts. 107 e 172."}, {"id": 2000000216, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pares", "frente": "Posse x porte ilegal de arma de uso permitido.", "verso": "Posse (art. 12): manter a arma dentro de casa ou no local de trabalho, sendo o responsável. Porte (art. 14): levar a arma fora desses locais.", "explicacao": "Lei 10.826/2003. Posse: detenção de 1 a 3 anos. Porte: reclusão de 2 a 4 anos."}, {"id": 2000000217, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a pena da posse ou porte de arma de uso restrito?", "verso": "Reclusão de 3 a 6 anos e multa.", "explicacao": "Lei 10.826/2003, art. 16. Se for de uso proibido: 4 a 12 anos (§ 2º)."}, {"id": 2000000218, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "O que é disparo de arma de fogo como crime?", "verso": "Disparar arma ou acionar munição em lugar habitado ou adjacências, em via pública ou em direção a ela, desde que não seja para praticar outro crime.", "explicacao": "Lei 10.826/2003, art. 15."}, {"id": 2000000219, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Qual a idade mínima para adquirir arma de fogo?", "verso": "25 anos.", "explicacao": "Lei 10.826/2003, art. 28 (com exceções para integrantes das forças de segurança)."}, {"id": 2000000220, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "pergunta", "frente": "Comércio ilegal e tráfico internacional de arma são hediondos?", "verso": "Sim, assim como a posse ou porte de arma de uso proibido.", "explicacao": "Lei 8.072/1990, art. 1º, parágrafo único."}, {"id": 2000000221, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Qual a pena base do crime de tortura?", "verso": "Reclusão de 2 a 8 anos.", "explicacao": "Lei 9.455/1997, art. 1º."}, {"id": 2000000222, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Quem se omite diante da tortura, tendo o dever de evitá-la, responde como?", "verso": "Detenção de 1 a 4 anos.", "explicacao": "Lei 9.455/1997, art. 1º, § 2º."}, {"id": 2000000223, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Qual o efeito da condenação por tortura para o servidor?", "verso": "Perda do cargo, função ou emprego público e interdição para seu exercício pelo dobro do prazo da pena aplicada. É efeito automático.", "explicacao": "Lei 9.455/1997, art. 1º, § 5º."}, {"id": 2000000224, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "Em que regime se inicia a pena por tortura (fora a omissão)?", "verso": "Regime fechado.", "explicacao": "Lei 9.455/1997, art. 1º, § 7º."}, {"id": 2000000225, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pergunta", "frente": "A lei de tortura alcança crime cometido no exterior?", "verso": "Sim, se a vítima for brasileira ou o agente estiver em local sob jurisdição brasileira.", "explicacao": "Lei 9.455/1997, art. 2º."}, {"id": 2000000226, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Cite crimes hediondos do CP.", "verso": "Homicídio qualificado e o praticado em atividade típica de grupo de extermínio, feminicídio, latrocínio, extorsão mediante sequestro, estupro e estupro de vulnerável, epidemia com resultado morte, entre outros.", "explicacao": "Lei 8.072/1990, art. 1º."}, {"id": 2000000227, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Quais crimes são equiparados a hediondos pela Constituição?", "verso": "Tortura, tráfico de drogas e terrorismo.", "explicacao": "CF, art. 5º, XLIII."}, {"id": 2000000228, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pares", "frente": "Progressão de regime: primário x reincidente em hediondo (sem morte).", "verso": "Primário: 40% da pena. Reincidente em hediondo: 60%.", "explicacao": "LEP, art. 112, V e VII (Pacote Anticrime). Com resultado morte: 50% (primário) e 70% (reincidente)."}, {"id": 2000000229, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "pergunta", "frente": "Condenado por hediondo pode receber indulto?", "verso": "Não. Hediondos e equiparados são insuscetíveis de anistia, graça e indulto, e de fiança.", "explicacao": "Lei 8.072/1990, art. 2º."}, {"id": 2000000230, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "O que é organização criminosa?", "verso": "Associação de 4 ou mais pessoas, estruturalmente ordenada, com divisão de tarefas, para obter vantagem mediante infrações com pena máxima superior a 4 anos ou de caráter transnacional.", "explicacao": "Lei 12.850/2013, art. 1º, § 1º."}, {"id": 2000000231, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pares", "frente": "Organização criminosa x associação criminosa.", "verso": "Organização: 4 ou mais pessoas, estrutura ordenada e divisão de tarefas (Lei 12.850). Associação: 3 ou mais pessoas para cometer crimes (CP, art. 288).", "explicacao": "Diferença no número mínimo e na estrutura."}, {"id": 2000000232, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Quais meios de obtenção de prova a Lei 12.850 prevê?", "verso": "Colaboração premiada, captação ambiental, ação controlada, acesso a registros e dados, interceptação, afastamento de sigilos, infiltração de agentes e cooperação entre instituições.", "explicacao": "Lei 12.850/2013, art. 3º."}, {"id": 2000000233, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "A ação controlada precisa de autorização judicial?", "verso": "Não precisa de autorização, mas deve ser previamente comunicada ao juiz, que pode estabelecer limites.", "explicacao": "Lei 12.850/2013, art. 8º, § 1º."}, {"id": 2000000234, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Qual o elemento subjetivo exigido nos crimes de abuso de autoridade?", "verso": "Finalidade específica de prejudicar outrem, beneficiar a si ou a terceiro, ou por mero capricho ou satisfação pessoal.", "explicacao": "Lei 13.869/2019, art. 1º, § 1º."}, {"id": 2000000235, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "certo_errado", "frente": "Certo ou errado? A divergência na interpretação da lei ou na avaliação de fatos e provas configura abuso de autoridade.", "verso": "Errado. Não configura, por si só (vedação ao crime de hermenêutica).", "explicacao": "Lei 13.869/2019, art. 1º, § 2º."}, {"id": 2000000236, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Qual a ação penal nos crimes de abuso de autoridade?", "verso": "Pública incondicionada, admitida a ação privada subsidiária.", "explicacao": "Lei 13.869/2019, art. 3º."}, {"id": 2000000237, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "A perda do cargo por abuso de autoridade é automática?", "verso": "Não. Depende de reincidência em crime de abuso e deve ser declarada motivadamente na sentença.", "explicacao": "Lei 13.869/2019, art. 4º, parágrafo único."}, {"id": 2000000238, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Constranger o preso, com violência, grave ameaça ou redução da capacidade de resistência, a exibir o corpo à curiosidade pública é crime?", "verso": "Sim, abuso de autoridade.", "explicacao": "Lei 13.869/2019, art. 13, I."}, {"id": 2000000239, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "pergunta", "frente": "Injúria racial: como está tratada hoje?", "verso": "Como crime de racismo, na Lei 7.716/1989 (art. 2º-A): imprescritível e inafiançável, com pena de reclusão de 2 a 5 anos.", "explicacao": "Lei 14.532/2023."}, {"id": 2000000240, "trilha": "policial", "materia": "leg", "assunto": "Racismo", "tipo": "certo_errado", "frente": "Certo ou errado? O crime de racismo prescreve em 20 anos.", "verso": "Errado. É imprescritível.", "explicacao": "CF, art. 5º, XLII."}, {"id": 2000000241, "trilha": "policial", "materia": "leg", "assunto": "Lei do delegado", "tipo": "pergunta", "frente": "Qual a natureza das funções do delegado de polícia?", "verso": "Funções de polícia judiciária e apuração de infrações penais, de natureza jurídica, essenciais e exclusivas de Estado.", "explicacao": "Lei 12.830/2013, art. 2º."}, {"id": 2000000242, "trilha": "policial", "materia": "leg", "assunto": "Lei do delegado", "tipo": "pergunta", "frente": "O inquérito pode ser avocado ou redistribuído livremente?", "verso": "Não. Só por superior hierárquico, por despacho fundamentado, por motivo de interesse público ou descumprimento de procedimentos.", "explicacao": "Lei 12.830/2013, art. 2º, § 4º."}, {"id": 2000000243, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Qual a pena do homicídio culposo na direção de veículo?", "verso": "Detenção de 2 a 4 anos e suspensão ou proibição da habilitação.", "explicacao": "CTB, art. 302."}, {"id": 2000000244, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "Homicídio culposo no trânsito com motorista embriagado: qual a pena?", "verso": "Reclusão de 5 a 8 anos.", "explicacao": "CTB, art. 302, § 3º."}, {"id": 2000000245, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "O que configura o crime de embriaguez ao volante?", "verso": "Conduzir veículo com capacidade psicomotora alterada por álcool (6 decigramas ou mais por litro de sangue, ou 0,3 mg por litro de ar alveolar) ou outra substância psicoativa.", "explicacao": "CTB, art. 306. Pena de detenção de 6 meses a 3 anos."}, {"id": 2000000246, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "pergunta", "frente": "O que é o crime de “racha”?", "verso": "Participar, em via pública, de corrida, disputa ou competição não autorizada, gerando situação de risco.", "explicacao": "CTB, art. 308."}, {"id": 2000000247, "trilha": "policial", "materia": "leg", "assunto": "Crimes de trânsito", "tipo": "certo_errado", "frente": "Certo ou errado? Ao condutor que presta pronto e integral socorro à vítima não se imporá prisão em flagrante nem fiança.", "verso": "Certo.", "explicacao": "CTB, art. 301."}, {"id": 2000000248, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Quais são as faltas graves cometidas pelo preso?", "verso": "Fuga, incitar ou participar de movimento para subverter a ordem, possuir instrumento capaz de ofender, ter aparelho celular, provocar acidente de trabalho, descumprir condições do regime aberto, não se submeter às ordens, recusar identificação genética.", "explicacao": "LEP, art. 50."}, {"id": 2000000249, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Como funciona a remição pelo estudo e pelo trabalho?", "verso": "Trabalho: 1 dia de pena a cada 3 dias de trabalho. Estudo: 1 dia a cada 12 horas de frequência escolar, divididas em no mínimo 3 dias.", "explicacao": "LEP, art. 126."}, {"id": 2000000250, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual a duração máxima do regime disciplinar diferenciado (RDD)?", "verso": "Até 2 anos, sem prejuízo de repetição por nova falta grave da mesma espécie.", "explicacao": "LEP, art. 52, I (Pacote Anticrime)."}, {"id": 2000000251, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "A falta grave interrompe o prazo para progressão de regime?", "verso": "Sim. O prazo recomeça a partir da falta.", "explicacao": "LEP, art. 112, § 6º, e Súmula 534 do STJ."}, {"id": 2000000252, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "certo_errado", "frente": "Certo ou errado? A falta grave interrompe o prazo para obter livramento condicional.", "verso": "Errado.", "explicacao": "Súmula 441 do STJ."}, {"id": 2000000253, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Depois da Lei 14.843/2024, a saída temporária ficou restrita a quê?", "verso": "À frequência a curso supletivo profissionalizante, de ensino médio ou superior, por condenados no semiaberto, pelo tempo necessário às atividades escolares.", "explicacao": "LEP, arts. 122 e 124. Acabaram as saídas para visitar a família."}, {"id": 2000000254, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "pergunta", "frente": "Quais as três fases clássicas da lavagem de dinheiro?", "verso": "Colocação (placement), ocultação ou dissimulação (layering) e integração.", "explicacao": "Doutrina sobre a Lei 9.613/1998."}, {"id": 2000000255, "trilha": "policial", "materia": "leg", "assunto": "Lavagem de dinheiro", "tipo": "certo_errado", "frente": "Certo ou errado? Desde a Lei 12.683/2012, qualquer infração penal pode ser antecedente da lavagem.", "verso": "Certo. Acabou o rol taxativo de crimes antecedentes.", "explicacao": "Lei 9.613/1998, art. 1º."}, {"id": 2000000256, "trilha": "policial", "materia": "leg", "assunto": "Terrorismo", "tipo": "certo_errado", "frente": "Certo ou errado? Manifestações sociais e reivindicatórias podem ser enquadradas como terrorismo.", "verso": "Errado. A lei exclui expressamente a conduta individual ou coletiva em manifestações políticas, movimentos sociais, sindicais ou religiosos.", "explicacao": "Lei 13.260/2016, art. 2º, § 2º."}, {"id": 2000000257, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "certo_errado", "frente": "Certo ou errado? A tentativa de contravenção penal é punível.", "verso": "Errado.", "explicacao": "Decreto-Lei 3.688/1941, art. 4º."}, {"id": 2000000258, "trilha": "policial", "materia": "leg", "assunto": "Contravenções penais", "tipo": "pergunta", "frente": "Qual a pena máxima de prisão simples nas contravenções?", "verso": "5 anos.", "explicacao": "LCP, art. 10."}, {"id": 2000000259, "trilha": "policial", "materia": "leg", "assunto": "Crimes ambientais", "tipo": "pergunta", "frente": "Pessoa jurídica pode responder por crime ambiental?", "verso": "Sim, administrativa, civil e penalmente.", "explicacao": "CF, art. 225, § 3º, e Lei 9.605/1998, art. 3º."}, {"id": 2000000260, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "A partir de que idade a pessoa é idosa pelo Estatuto?", "verso": "60 anos.", "explicacao": "Lei 10.741/2003, art. 1º."}, {"id": 2000000261, "trilha": "policial", "materia": "leg", "assunto": "Estatuto da Pessoa Idosa", "tipo": "pergunta", "frente": "Qual a ação penal nos crimes do Estatuto da Pessoa Idosa?", "verso": "Pública incondicionada.", "explicacao": "Lei 10.741/2003, art. 95."}, {"id": 2000000262, "trilha": "policial", "materia": "leg", "assunto": "Identificação criminal", "tipo": "pergunta", "frente": "Quem já é civilmente identificado pode ser identificado criminalmente?", "verso": "Só nas hipóteses da lei: documento rasurado ou insuficiente, documentos conflitantes, essencial às investigações por decisão judicial, entre outras.", "explicacao": "CF, art. 5º, LVIII, e Lei 12.037/2009, art. 3º."}, {"id": 2000000263, "trilha": "policial", "materia": "leg", "assunto": "Interceptação", "tipo": "pergunta", "frente": "Interceptar comunicações sem autorização judicial é crime?", "verso": "Sim: reclusão de 2 a 4 anos e multa.", "explicacao": "Lei 9.296/1996, art. 10."}, {"id": 2000000264, "trilha": "policial", "materia": "leg", "assunto": "Juizados Especiais", "tipo": "pergunta", "frente": "Composição civil dos danos homologada: qual o efeito na ação privada ou condicionada?", "verso": "Acarreta renúncia ao direito de queixa ou representação.", "explicacao": "Lei 9.099/1995, art. 74, parágrafo único."}, {"id": 2000000265, "trilha": "policial", "materia": "leg", "assunto": "Estatuto do Desarmamento", "tipo": "certo_errado", "frente": "Certo ou errado? Arma com registro vencido configura crime de posse ilegal.", "verso": "Errado, segundo o STJ: é infração administrativa.", "explicacao": "STJ, APn 686 e julgados posteriores, para arma de uso permitido."}, {"id": 2000000266, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "Quem pode ser preso em flagrante pelo porte para consumo pessoal?", "verso": "Ninguém. Não se impõe prisão em flagrante; o autor é encaminhado ao juízo ou assina termo de compromisso.", "explicacao": "Lei 11.343/2006, art. 48, § 2º."}, {"id": 2000000267, "trilha": "policial", "materia": "leg", "assunto": "Lei de Drogas", "tipo": "pergunta", "frente": "O laudo de constatação da droga basta para prender em flagrante?", "verso": "Sim. Para o auto de prisão em flagrante basta o laudo de constatação da natureza e quantidade, por perito oficial ou pessoa idônea.", "explicacao": "Lei 11.343/2006, art. 50, § 1º."}, {"id": 2000000268, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "pergunta", "frente": "Em quanto tempo o adolescente apreendido deve ser liberado ou apresentado ao MP?", "verso": "A autoridade policial deve apresentá-lo ao MP de imediato ou, não sendo possível, em até 24 horas.", "explicacao": "ECA, art. 175."}, {"id": 2000000269, "trilha": "policial", "materia": "leg", "assunto": "ECA", "tipo": "certo_errado", "frente": "Certo ou errado? O adolescente pode ser transportado em compartimento fechado de viatura em condições que atentem contra sua dignidade.", "verso": "Errado.", "explicacao": "ECA, art. 178."}, {"id": 2000000270, "trilha": "policial", "materia": "leg", "assunto": "Lei de Tortura", "tipo": "pares", "frente": "Tortura-prova, tortura-crime e tortura-discriminação.", "verso": "Prova: para obter informação, declaração ou confissão. Crime: para provocar ação ou omissão criminosa. Discriminação: em razão de discriminação racial ou religiosa.", "explicacao": "Lei 9.455/1997, art. 1º, I, a, b e c."}, {"id": 2000000271, "trilha": "policial", "materia": "leg", "assunto": "Maria da Penha", "tipo": "pergunta", "frente": "A Lei Maria da Penha protege mulheres trans?", "verso": "Sim, segundo o STJ (REsp 1.977.124/SP, 2022).", "explicacao": "Gênero, não sexo biológico, é o critério de proteção."}, {"id": 2000000272, "trilha": "policial", "materia": "leg", "assunto": "Organizações criminosas", "tipo": "pergunta", "frente": "Qual a pena de promover, constituir ou integrar organização criminosa?", "verso": "Reclusão de 3 a 8 anos e multa.", "explicacao": "Lei 12.850/2013, art. 2º."}, {"id": 2000000273, "trilha": "policial", "materia": "leg", "assunto": "Abuso de autoridade", "tipo": "pergunta", "frente": "Decretar prisão em manifesta desconformidade com a lei é crime de abuso?", "verso": "Sim.", "explicacao": "Lei 13.869/2019, art. 9º."}, {"id": 2000000274, "trilha": "policial", "materia": "leg", "assunto": "Execução penal", "tipo": "pergunta", "frente": "Qual a progressão de regime para crime cometido com violência ou grave ameaça por primário?", "verso": "25% da pena.", "explicacao": "LEP, art. 112, III. Sem violência, primário: 16%."}, {"id": 2000000275, "trilha": "policial", "materia": "leg", "assunto": "Crimes hediondos", "tipo": "certo_errado", "frente": "Certo ou errado? O tráfico privilegiado (art. 33, § 4º, da Lei de Drogas) é crime hediondo.", "verso": "Errado.", "explicacao": "STF (HC 118.533) e Lei 7.210/1984, art. 112, § 5º."}, {"id": 2000000276, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que é poder de polícia?", "verso": "Atividade da Administração que limita ou disciplina direito, interesse ou liberdade, em razão do interesse público.", "explicacao": "CTN, art. 78."}, {"id": 2000000277, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "Quais os atributos do poder de polícia?", "verso": "Discricionariedade, autoexecutoriedade e coercibilidade.", "explicacao": "Mnemônico DAC."}, {"id": 2000000278, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "Quais os ciclos do poder de polícia?", "verso": "Ordem, consentimento, fiscalização e sanção.", "explicacao": "Doutrina. O STF admite delegar consentimento e fiscalização a estatais de direito privado (RE 633.782)."}, {"id": 2000000279, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pares", "frente": "Poder hierárquico x poder disciplinar.", "verso": "Hierárquico: organizar, ordenar, rever, delegar e avocar dentro da estrutura. Disciplinar: apurar infrações e aplicar penalidades a servidores e a quem tem vínculo especial.", "explicacao": "Doutrina de Direito Administrativo."}, {"id": 2000000280, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pares", "frente": "Excesso de poder x desvio de finalidade.", "verso": "Excesso: o agente vai além da sua competência. Desvio: age dentro da competência, mas com finalidade diversa da prevista em lei.", "explicacao": "São as duas espécies de abuso de poder."}, {"id": 2000000281, "trilha": "policial", "materia": "adm", "assunto": "Poderes administrativos", "tipo": "pergunta", "frente": "O que não pode ser objeto de delegação (Lei 9.784)?", "verso": "Edição de atos normativos, decisão de recursos administrativos e matérias de competência exclusiva.", "explicacao": "Lei 9.784/1999, art. 13."}, {"id": 2000000282, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais os elementos (requisitos) do ato administrativo?", "verso": "Competência, finalidade, forma, motivo e objeto.", "explicacao": "Mnemônico COFIFOMOB. Competência, finalidade e forma são vinculados."}, {"id": 2000000283, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Quais os atributos do ato administrativo?", "verso": "Presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade.", "explicacao": "Mnemônico PATI."}, {"id": 2000000284, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Anulação x revogação.", "verso": "Anulação: por ilegalidade, pela Administração ou pelo Judiciário, com efeitos retroativos (ex tunc). Revogação: por conveniência e oportunidade, só pela Administração, efeitos a partir de então (ex nunc).", "explicacao": "Súmula 473 do STF."}, {"id": 2000000285, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "Qual o prazo para a Administração anular atos que beneficiam o administrado de boa-fé?", "verso": "5 anos.", "explicacao": "Lei 9.784/1999, art. 54."}, {"id": 2000000286, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pergunta", "frente": "O que diz a teoria dos motivos determinantes?", "verso": "Se o ato foi motivado, sua validade fica vinculada à veracidade dos motivos declarados, mesmo que a motivação não fosse obrigatória.", "explicacao": "Doutrina e jurisprudência."}, {"id": 2000000287, "trilha": "policial", "materia": "adm", "assunto": "Ato administrativo", "tipo": "pares", "frente": "Ato vinculado x ato discricionário.", "verso": "Vinculado: a lei fixa todos os elementos, sem margem de escolha. Discricionário: a lei deixa margem de conveniência e oportunidade quanto ao motivo e ao objeto.", "explicacao": "O mérito administrativo existe só no ato discricionário."}, {"id": 2000000288, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz a Súmula Vinculante 13?", "verso": "Proíbe o nepotismo: nomear cônjuge, companheiro ou parente até o 3º grau da autoridade nomeante ou de servidor em cargo de direção, chefia ou assessoramento, para cargo em comissão ou função de confiança.", "explicacao": "Súmula Vinculante 13 do STF."}, {"id": 2000000289, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pergunta", "frente": "Quais os princípios do art. 37 da Constituição?", "verso": "Legalidade, impessoalidade, moralidade, publicidade e eficiência.", "explicacao": "LIMPE. A eficiência entrou com a EC 19/1998."}, {"id": 2000000290, "trilha": "policial", "materia": "adm", "assunto": "Princípios", "tipo": "pares", "frente": "Legalidade para o particular x para a Administração.", "verso": "Particular: pode fazer tudo o que a lei não proíbe. Administração: só pode fazer o que a lei autoriza.", "explicacao": "Princípio da legalidade estrita."}, {"id": 2000000291, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pares", "frente": "Descentralização x desconcentração.", "verso": "Descentralização: transfere a atividade para outra pessoa jurídica (autarquia, empresa pública…). Desconcentração: distribui competências entre órgãos da mesma pessoa, com hierarquia.", "explicacao": "Mnemônico: desCOncentração = COmpetências internas."}, {"id": 2000000292, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "Quais entidades compõem a Administração indireta?", "verso": "Autarquias, fundações públicas, empresas públicas e sociedades de economia mista.", "explicacao": "Decreto-Lei 200/1967, art. 4º."}, {"id": 2000000293, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pares", "frente": "Empresa pública x sociedade de economia mista.", "verso": "Empresa pública: capital 100% público, qualquer forma societária. Economia mista: maioria do capital votante público, sempre sociedade anônima.", "explicacao": "Lei 13.303/2016."}, {"id": 2000000294, "trilha": "policial", "materia": "adm", "assunto": "Organização", "tipo": "pergunta", "frente": "Autarquia tem personalidade jurídica de direito público ou privado?", "verso": "De direito público, criada por lei específica.", "explicacao": "CF, art. 37, XIX."}, {"id": 2000000295, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "Qual teoria fundamenta a responsabilidade objetiva do Estado?", "verso": "Teoria do risco administrativo, que admite excludentes (culpa exclusiva da vítima, caso fortuito, força maior, fato de terceiro).", "explicacao": "CF, art. 37, § 6º."}, {"id": 2000000296, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "A vítima pode processar diretamente o agente público que causou o dano?", "verso": "Não. Deve acionar o Estado, que tem ação de regresso contra o agente em caso de dolo ou culpa.", "explicacao": "STF, Tema 940 (dupla garantia)."}, {"id": 2000000297, "trilha": "policial", "materia": "adm", "assunto": "Responsabilidade civil", "tipo": "pergunta", "frente": "O Estado responde pela morte de preso sob sua custódia?", "verso": "Sim, objetivamente, quando descumprido seu dever de proteção.", "explicacao": "STF, Tema 592 (RE 841.526)."}, {"id": 2000000298, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "pergunta", "frente": "Quais as espécies de improbidade administrativa?", "verso": "Enriquecimento ilícito (art. 9º), lesão ao erário (art. 10) e atentado aos princípios (art. 11).", "explicacao": "Lei 8.429/1992."}, {"id": 2000000299, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "certo_errado", "frente": "Certo ou errado? Após a Lei 14.230/2021, existe improbidade culposa.", "verso": "Errado. Todas as modalidades exigem dolo.", "explicacao": "Lei 8.429/1992, art. 1º, §§ 1º a 3º."}, {"id": 2000000300, "trilha": "policial", "materia": "adm", "assunto": "Improbidade", "tipo": "certo_errado", "frente": "Certo ou errado? A ação de improbidade tem natureza penal.", "verso": "Errado. Tem natureza civil, sem prejuízo da ação penal cabível.", "explicacao": "CF, art. 37, § 4º."}, {"id": 2000000301, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Quais as penalidades da Lei 8.112/1990?", "verso": "Advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade, destituição de cargo em comissão e destituição de função comissionada.", "explicacao": "Lei 8.112/1990, art. 127."}, {"id": 2000000302, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Qual o prazo máximo da suspensão disciplinar na Lei 8.112?", "verso": "90 dias.", "explicacao": "Lei 8.112/1990, art. 130."}, {"id": 2000000303, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pares", "frente": "Sindicância x processo administrativo disciplinar (PAD).", "verso": "Sindicância: pode resultar em arquivamento, advertência ou suspensão de até 30 dias. PAD: obrigatório para suspensão acima de 30 dias, demissão e cassação.", "explicacao": "Lei 8.112/1990, arts. 145 e 146."}, {"id": 2000000304, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "Qual o prazo para concluir o PAD?", "verso": "60 dias, prorrogáveis por igual período.", "explicacao": "Lei 8.112/1990, art. 152."}, {"id": 2000000305, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "certo_errado", "frente": "Certo ou errado? A falta de defesa técnica por advogado no PAD ofende a Constituição.", "verso": "Errado.", "explicacao": "Súmula Vinculante 5 do STF."}, {"id": 2000000306, "trilha": "policial", "materia": "adm", "assunto": "Processo disciplinar", "tipo": "pergunta", "frente": "A absolvição criminal sempre impede a punição administrativa?", "verso": "Não. Só quando a absolvição negar a existência do fato ou a autoria.", "explicacao": "Lei 8.112/1990, art. 126."}, {"id": 2000000307, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pares", "frente": "Cargo efetivo x cargo em comissão.", "verso": "Efetivo: provido por concurso, gera estabilidade. Comissão: livre nomeação e exoneração, para direção, chefia e assessoramento.", "explicacao": "CF, art. 37, II e V."}, {"id": 2000000308, "trilha": "policial", "materia": "adm", "assunto": "Servidores", "tipo": "pergunta", "frente": "Qual o prazo para o servidor nomeado tomar posse e, depois, entrar em exercício (Lei 8.112)?", "verso": "Posse: 30 dias da nomeação. Exercício: 15 dias da posse.", "explicacao": "Lei 8.112/1990, arts. 13, § 1º, e 15, § 1º."}, {"id": 2000000309, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pergunta", "frente": "Quais as modalidades de licitação na Lei 14.133/2021?", "verso": "Pregão, concorrência, concurso, leilão e diálogo competitivo.", "explicacao": "Lei 14.133/2021, art. 28. Acabaram tomada de preços e convite."}, {"id": 2000000310, "trilha": "policial", "materia": "adm", "assunto": "Licitações", "tipo": "pares", "frente": "Licitação dispensável x inexigível.", "verso": "Dispensável: a competição é possível, mas a lei permite não licitar. Inexigível: a competição é inviável (ex.: fornecedor exclusivo).", "explicacao": "Lei 14.133/2021, arts. 74 e 75."}, {"id": 2000000311, "trilha": "policial", "materia": "adm", "assunto": "Controle", "tipo": "pergunta", "frente": "O Judiciário pode controlar o mérito do ato administrativo?", "verso": "Não. Controla a legalidade, inclusive a razoabilidade e proporcionalidade, mas não substitui a conveniência e oportunidade do administrador.", "explicacao": "Princípio da separação dos Poderes."}, {"id": 2000000312, "trilha": "policial", "materia": "adm", "assunto": "Bens públicos", "tipo": "pergunta", "frente": "Quais as características dos bens públicos?", "verso": "Inalienabilidade (relativa), imprescritibilidade (não sofrem usucapião), impenhorabilidade e não onerabilidade.", "explicacao": "CF, arts. 183, § 3º, e 191, parágrafo único."}, {"id": 2000000313, "trilha": "policial", "materia": "adm", "assunto": "Serviços públicos", "tipo": "pares", "frente": "Concessão x permissão de serviço público.", "verso": "Concessão: contrato, por concorrência ou diálogo competitivo, com pessoa jurídica ou consórcio. Permissão: contrato de adesão, precário, com pessoa física ou jurídica.", "explicacao": "Lei 8.987/1995, art. 2º."}, {"id": 2000000314, "trilha": "policial", "materia": "adm", "assunto": "Agentes públicos", "tipo": "pergunta", "frente": "O policial que age no exercício da função representa quem perante terceiros?", "verso": "O próprio Estado, segundo a teoria do órgão (imputação): seus atos são imputados à pessoa jurídica.", "explicacao": "Teoria de Otto Gierke."}, {"id": 2000000315, "trilha": "policial", "materia": "adm", "assunto": "Processo administrativo", "tipo": "pergunta", "frente": "Qual o prazo geral para recurso administrativo na Lei 9.784?", "verso": "10 dias.", "explicacao": "Lei 9.784/1999, art. 59."}, {"id": 2000000316, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Qual a regra básica da crase?", "verso": "Ocorre quando a preposição “a” se junta ao artigo feminino “a(s)”, ou ao “a” inicial de aquele(s), aquela(s), aquilo.", "explicacao": "Teste: troque por uma palavra masculina. Se virar “ao”, há crase: “fui à delegacia / fui ao fórum”."}, {"id": 2000000317, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? Há crase em “Ele começou a estudar”.", "verso": "Errado. Não há crase antes de verbo.", "explicacao": "Também não há antes de palavra masculina (salvo “à moda de”) e de pronomes como ela, esta, você."}, {"id": 2000000318, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Usa-se crase em “às vezes”, “à noite” e “à medida que”?", "verso": "Sim. São locuções adverbiais e conjuntivas femininas.", "explicacao": "Locuções femininas levam crase: às pressas, à tarde, à custa de."}, {"id": 2000000319, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "certo_errado", "frente": "Certo ou errado? “Chegou a uma conclusão” leva crase.", "verso": "Errado. Não há crase antes do artigo indefinido “uma”.", "explicacao": "Exceção: indicando hora (“à uma hora”)."}, {"id": 2000000320, "trilha": "policial", "materia": "port", "assunto": "Crase", "tipo": "pergunta", "frente": "Crase antes de nome de cidade: como saber?", "verso": "Use o teste “volto de / volto da”. Se voltar DA, há crase (vou à Bahia); se voltar DE, não há (vou a Salvador).", "explicacao": "Com cidade especificada há crase: “vou à Salvador antiga”."}, {"id": 2000000321, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Haviam muitos candidatos na sala.”", "verso": "Errado. O verbo haver, no sentido de existir, é impessoal: “Havia muitos candidatos”.", "explicacao": "O verbo auxiliar acompanha: “Deve haver muitos candidatos”."}, {"id": 2000000322, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Fazem dois anos que estudo para concurso.”", "verso": "Errado. Fazer indicando tempo decorrido é impessoal: “Faz dois anos”.", "explicacao": "Mesmo caso de “haver” indicando tempo: “Há dois anos”."}, {"id": 2000000323, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "Com a partícula “se” apassivadora, como fica o verbo: “Vende(m)-se casas”?", "verso": "“Vendem-se casas”: o verbo concorda com o sujeito (casas são vendidas).", "explicacao": "Com verbo que pede preposição, o “se” indetermina o sujeito e o verbo fica no singular: “Precisa-se de vendedores”."}, {"id": 2000000324, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "certo_errado", "frente": "Certo ou errado? “Seguem anexo os documentos.”", "verso": "Errado. “Anexo” é adjetivo e concorda: “Seguem anexos os documentos”.", "explicacao": "“Em anexo” é invariável."}, {"id": 2000000325, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“Meio” no sentido de “um pouco” varia? “Ela está meio cansada.”", "verso": "Não varia: é advérbio. “Meia” só quando significa metade (meia hora).", "explicacao": "Mesma lógica para “bastante” (advérbio, invariável) e “menos” (sempre invariável)."}, {"id": 2000000326, "trilha": "policial", "materia": "port", "assunto": "Concordância", "tipo": "pergunta", "frente": "“É proibido entrada” ou “É proibida a entrada”?", "verso": "As duas estão certas. Sem artigo, fica invariável; com artigo, concorda.", "explicacao": "Vale para “é necessário”, “é bom”, “é permitido”."}, {"id": 2000000327, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Assistir no sentido de ver pede preposição?", "verso": "Sim: “assistir ao jogo”.", "explicacao": "Assistir no sentido de ajudar é transitivo direto: “o médico assistiu o paciente”."}, {"id": 2000000328, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência correta de “preferir”?", "verso": "Preferir algo A outra coisa: “Prefiro estudar a dormir”.", "explicacao": "É errado “prefiro mais… do que…”."}, {"id": 2000000329, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência de “obedecer”?", "verso": "Pede a preposição “a”: “obedecer ao regulamento”.", "explicacao": "Desobedecer também: “desobedecer à ordem”."}, {"id": 2000000330, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "Qual a regência de “aspirar” no sentido de desejar?", "verso": "Pede a preposição “a”: “aspiro ao cargo”.", "explicacao": "No sentido de respirar/sorver, é direto: “aspirar o ar”."}, {"id": 2000000331, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Implicar” no sentido de acarretar pede preposição?", "verso": "Não: “A decisão implica prejuízos” (sem “em”).", "explicacao": "Implicar com alguém (antipatizar) pede “com”."}, {"id": 2000000332, "trilha": "policial", "materia": "port", "assunto": "Regência", "tipo": "pergunta", "frente": "“Chegar” pede qual preposição?", "verso": "A preposição “a”: “Chegou à delegacia”, “chegou a Brasília”.", "explicacao": "Na norma-padrão, evite “chegou na delegacia”."}, {"id": 2000000333, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "pergunta", "frente": "O que atrai o pronome para antes do verbo (próclise)?", "verso": "Palavras negativas, pronomes relativos, advérbios, conjunções subordinativas, pronomes indefinidos e interrogativos.", "explicacao": "Ex.: “Não me disseram”, “quem te contou”, “aqui se estuda”."}, {"id": 2000000334, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "certo_errado", "frente": "Certo ou errado? Na norma-padrão, pode-se começar frase com pronome oblíquo: “Me disseram a verdade.”", "verso": "Errado. Não se inicia período com pronome oblíquo átono: “Disseram-me a verdade”.", "explicacao": "Uso aceito na fala, mas não na norma-padrão."}, {"id": 2000000335, "trilha": "policial", "materia": "port", "assunto": "Colocação pronominal", "tipo": "pergunta", "frente": "Pode haver ênclise com verbo no futuro do presente ou do pretérito?", "verso": "Não. Usa-se mesóclise (“far-se-á”) ou próclise, se houver atrativo (“não se fará”).", "explicacao": "A ênclise com futuro é sempre errada."}, {"id": 2000000336, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "certo_errado", "frente": "Certo ou errado? Pode-se separar sujeito e verbo por vírgula: “Os candidatos aprovados, foram convocados.”", "verso": "Errado. Não se separa sujeito do verbo com vírgula.", "explicacao": "Só se houver termo intercalado entre duas vírgulas."}, {"id": 2000000337, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "O vocativo deve vir isolado por vírgula?", "verso": "Sim: “Maria, venha aqui.”", "explicacao": "Vocativo é o termo usado para chamar o interlocutor."}, {"id": 2000000338, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Oração adjetiva explicativa x restritiva: o que muda na pontuação?", "verso": "A explicativa vem entre vírgulas e generaliza. A restritiva vem sem vírgulas e delimita.", "explicacao": "“Os alunos, que estudaram, passaram” (todos estudaram) x “Os alunos que estudaram passaram” (só alguns)."}, {"id": 2000000339, "trilha": "policial", "materia": "port", "assunto": "Pontuação", "tipo": "pergunta", "frente": "Deve-se usar vírgula antes de “e”?", "verso": "Em regra, não. Usa-se quando os sujeitos são diferentes, com “e” repetido (polissíndeto) ou com valor adversativo.", "explicacao": "“Ele estudou muito, e o irmão não abriu um livro.”"}, {"id": 2000000340, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pares", "frente": "Conjunções adversativas x concessivas.", "verso": "Adversativas ligam ideias opostas em orações coordenadas: mas, porém, contudo, todavia, entretanto. Concessivas introduzem uma ressalva que não impede o fato: embora, ainda que, conquanto, mesmo que.", "explicacao": "Embora pede subjuntivo: “Embora estude, não passa”."}, {"id": 2000000341, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressam “portanto”, “logo” e “por conseguinte”?", "verso": "Conclusão.", "explicacao": "São conjunções coordenativas conclusivas."}, {"id": 2000000342, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “à medida que”?", "verso": "Proporção.", "explicacao": "“Na medida em que” indica causa."}, {"id": 2000000343, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “conforme” em “Conforme previsto, a prova foi adiada”?", "verso": "Conformidade.", "explicacao": "Equivale a “como”, “segundo”, “consoante”."}, {"id": 2000000344, "trilha": "policial", "materia": "port", "assunto": "Conjunções", "tipo": "pergunta", "frente": "Que ideia expressa “desde que” em “Pode sair, desde que volte cedo”?", "verso": "Condição.", "explicacao": "Também pode indicar tempo: “Desde que chegou, não parou”."}, {"id": 2000000345, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Por que x porque x por quê x porquê.", "verso": "Por que: perguntas e “pelo qual”. Porque: explicação/causa. Por quê: no fim da frase. Porquê: substantivo (“o porquê”).", "explicacao": "“Não sei por que faltou” = “o motivo pelo qual”."}, {"id": 2000000346, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Mal x mau.", "verso": "Mal é o oposto de bem. Mau é o oposto de bom.", "explicacao": "“Ele agiu mal” / “Ele é um mau policial”."}, {"id": 2000000347, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Onde x aonde.", "verso": "Onde: lugar em que se está (verbos estáticos). Aonde: lugar para onde se vai (verbos de movimento).", "explicacao": "“Onde você mora?” / “Aonde você vai?”."}, {"id": 2000000348, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Ratificar x retificar.", "verso": "Ratificar: confirmar. Retificar: corrigir.", "explicacao": "Clássico de prova."}, {"id": 2000000349, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Mandado x mandato.", "verso": "Mandado: ordem judicial (mandado de prisão). Mandato: período de exercício de cargo eletivo ou procuração.", "explicacao": "“Cumprir mandado de busca” / “mandato de deputado”."}, {"id": 2000000350, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Deferir x diferir.", "verso": "Deferir: atender, conceder. Diferir: adiar ou diferenciar.", "explicacao": "“O juiz deferiu o pedido”."}, {"id": 2000000351, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Infligir x infringir.", "verso": "Infligir: aplicar pena ou castigo. Infringir: violar, transgredir.", "explicacao": "“Infringiu a lei e o juiz lhe infligiu a pena”."}, {"id": 2000000352, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Ao encontro de x de encontro a.", "verso": "Ao encontro de: a favor, concordância. De encontro a: contra, choque.", "explicacao": "“A proposta veio ao encontro dos meus interesses”."}, {"id": 2000000353, "trilha": "policial", "materia": "port", "assunto": "Ortografia", "tipo": "pares", "frente": "Acerca de x a cerca de x há cerca de.", "verso": "Acerca de: sobre, a respeito de. A cerca de: aproximadamente (distância/futuro). Há cerca de: faz aproximadamente (tempo passado).", "explicacao": "“Falou acerca do crime”; “fica a cerca de 2 km”; “chegou há cerca de 1 hora”."}, {"id": 2000000354, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "pergunta", "frente": "Por que “polícia” é acentuada?", "verso": "É paroxítona terminada em ditongo crescente (-ia).", "explicacao": "Também: história, série, ciência."}, {"id": 2000000355, "trilha": "policial", "materia": "port", "assunto": "Acentuação", "tipo": "certo_errado", "frente": "Certo ou errado? Pelo Acordo Ortográfico, “ideia” e “heroico” não têm mais acento.", "verso": "Certo. Caiu o acento dos ditongos abertos “ei” e “oi” nas paroxítonas.", "explicacao": "Nas oxítonas continua: herói, papéis."}, {"id": 2000000356, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Qual o particípio de “aceitar” com “ter” e com “ser”?", "verso": "Com ter/haver: aceitado. Com ser/estar: aceito.", "explicacao": "Mesma regra para entregar (entregado/entregue) e prender (prendido/preso)."}, {"id": 2000000357, "trilha": "policial", "materia": "port", "assunto": "Morfologia", "tipo": "pergunta", "frente": "Qual o plural de “cidadão”?", "verso": "Cidadãos.", "explicacao": "Também: irmãos, cristãos. Já “pão” faz pães e “leão” faz leões."}, {"id": 2000000358, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Em “Choveu muito ontem”, qual o sujeito?", "verso": "Oração sem sujeito (sujeito inexistente).", "explicacao": "Verbos que indicam fenômenos da natureza são impessoais."}, {"id": 2000000359, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pares", "frente": "Voz passiva analítica x sintética.", "verso": "Analítica: ser + particípio (“O réu foi preso pela polícia”). Sintética: verbo + se (“Prenderam-se os réus” = os réus foram presos).", "explicacao": "Na sintética, o verbo concorda com o sujeito paciente."}, {"id": 2000000360, "trilha": "policial", "materia": "port", "assunto": "Sintaxe", "tipo": "pergunta", "frente": "Em “Tenho certeza de que passarei”, que oração é “de que passarei”?", "verso": "Oração subordinada substantiva completiva nominal.", "explicacao": "Completa o substantivo “certeza”."}, {"id": 2000000361, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pergunta", "frente": "O que é pressuposto no texto?", "verso": "Informação implícita que decorre de uma palavra ou expressão do enunciado.", "explicacao": "“Ele parou de fumar” pressupõe que fumava antes."}, {"id": 2000000362, "trilha": "policial", "materia": "port", "assunto": "Interpretação", "tipo": "pares", "frente": "Denotação x conotação.", "verso": "Denotação: sentido literal, de dicionário. Conotação: sentido figurado.", "explicacao": "“O policial é uma rocha” (conotação)."}, {"id": 2000000363, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é metonímia?", "verso": "Troca de uma palavra por outra com a qual tem relação de proximidade (autor pela obra, parte pelo todo, marca pelo produto).", "explicacao": "“Li Machado de Assis” / “Pediu um Bombril”."}, {"id": 2000000364, "trilha": "policial", "materia": "port", "assunto": "Figuras de linguagem", "tipo": "pergunta", "frente": "O que é eufemismo?", "verso": "Suavizar uma ideia desagradável.", "explicacao": "“Ele partiu desta para melhor” (morreu)."}, {"id": 2000000365, "trilha": "policial", "materia": "port", "assunto": "Redação oficial", "tipo": "pergunta", "frente": "Quais atributos a redação oficial deve ter?", "verso": "Clareza, precisão, objetividade, concisão, coesão e coerência, impessoalidade, formalidade e padronização, e uso da norma-padrão.", "explicacao": "Manual de Redação da Presidência da República (3ª edição, 2018)."}, {"id": 2000000366, "trilha": "policial", "materia": "dh", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais as características dos direitos humanos?", "verso": "Universalidade, inerência, indivisibilidade, interdependência, inalienabilidade, imprescritibilidade, irrenunciabilidade, historicidade e vedação ao retrocesso.", "explicacao": "Doutrina; Declaração e Programa de Ação de Viena (1993)."}, {"id": 2000000367, "trilha": "policial", "materia": "dh", "assunto": "Gerações", "tipo": "pares", "frente": "Direitos de 1ª, 2ª e 3ª geração (dimensão).", "verso": "1ª: liberdade (civis e políticos). 2ª: igualdade (sociais, econômicos e culturais). 3ª: fraternidade (paz, meio ambiente, desenvolvimento).", "explicacao": "Lema da Revolução Francesa: liberdade, igualdade, fraternidade."}, {"id": 2000000368, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "pergunta", "frente": "Em que ano foi adotada a Declaração Universal dos Direitos Humanos?", "verso": "1948, pela Assembleia Geral da ONU.", "explicacao": "Resolução 217-A (III), de 10 de dezembro de 1948."}, {"id": 2000000369, "trilha": "policial", "materia": "dh", "assunto": "Sistema global", "tipo": "certo_errado", "frente": "Certo ou errado? A Declaração Universal dos Direitos Humanos é um tratado internacional.", "verso": "Errado. Foi adotada como resolução da Assembleia Geral, embora hoje seja vista como costume internacional.", "explicacao": "Doutrina majoritária."}, {"id": 2000000370, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o nome do principal tratado do sistema interamericano?", "verso": "Convenção Americana sobre Direitos Humanos (Pacto de São José da Costa Rica), de 1969.", "explicacao": "Promulgada no Brasil pelo Decreto 678/1992."}, {"id": 2000000371, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Qual o status do Pacto de São José no Brasil, segundo o STF?", "verso": "Supralegal: abaixo da Constituição e acima das leis.", "explicacao": "STF, RE 466.343. Por isso caiu a prisão do depositário infiel."}, {"id": 2000000372, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Quais os órgãos do sistema interamericano de proteção?", "verso": "Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos.", "explicacao": "Convenção Americana, art. 33."}, {"id": 2000000373, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "Pessoa física pode levar um caso diretamente à Corte Interamericana?", "verso": "Não. Só os Estados-partes e a Comissão podem submeter casos à Corte. O indivíduo peticiona à Comissão.", "explicacao": "Convenção Americana, arts. 44 e 61."}, {"id": 2000000374, "trilha": "policial", "materia": "dh", "assunto": "Sistema interamericano", "tipo": "pergunta", "frente": "O que prevê o Pacto de São José sobre a pessoa presa?", "verso": "Deve ser conduzida, sem demora, à presença de um juiz.", "explicacao": "Art. 7.5. Base da audiência de custódia."}, {"id": 2000000375, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "Quais princípios regem o uso da força por agentes de segurança?", "verso": "Legalidade, necessidade, proporcionalidade, moderação e conveniência.", "explicacao": "Portaria Interministerial 4.226/2010 e Lei 13.060/2014."}, {"id": 2000000376, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "certo_errado", "frente": "Certo ou errado? É legítimo atirar em pessoa em fuga, desarmada, que não representa risco imediato.", "verso": "Errado.", "explicacao": "Portaria Interministerial 4.226/2010, diretriz 4."}, {"id": 2000000377, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "certo_errado", "frente": "Certo ou errado? É legítimo atirar contra veículo que fura bloqueio sem representar risco imediato de morte ou lesão.", "verso": "Errado.", "explicacao": "Portaria Interministerial 4.226/2010, diretriz 5."}, {"id": 2000000378, "trilha": "policial", "materia": "dh", "assunto": "Uso da força", "tipo": "pergunta", "frente": "O que a Lei 13.060/2014 determina sobre instrumentos de menor potencial ofensivo?", "verso": "Os órgãos de segurança devem priorizar seu uso, desde que não coloquem em risco a integridade física ou psíquica dos policiais.", "explicacao": "Lei 13.060/2014, art. 2º."}, {"id": 2000000379, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "O Brasil ratificou a Convenção da ONU contra a Tortura?", "verso": "Sim. Promulgada pelo Decreto 40/1991.", "explicacao": "Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes (1984)."}, {"id": 2000000380, "trilha": "policial", "materia": "dh", "assunto": "Tortura", "tipo": "pergunta", "frente": "Ordem de superior hierárquico justifica a tortura?", "verso": "Não. Nenhuma circunstância excepcional ou ordem superior pode ser invocada como justificativa.", "explicacao": "Convenção da ONU contra a Tortura, art. 2º."}, {"id": 2000000381, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "O que são as Regras de Mandela?", "verso": "Regras Mínimas da ONU para o Tratamento de Presos, revisadas em 2015.", "explicacao": "Ex.: proíbem confinamento solitário prolongado (mais de 15 dias consecutivos)."}, {"id": 2000000382, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "O que são as Regras de Bangkok?", "verso": "Regras da ONU para o tratamento de mulheres presas e medidas não privativas de liberdade para mulheres infratoras.", "explicacao": "Aprovadas em 2010."}, {"id": 2000000383, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Quando cabe o incidente de deslocamento de competência para a Justiça Federal?", "verso": "Em grave violação de direitos humanos, para assegurar obrigações de tratados, a pedido do Procurador-Geral da República ao STJ.", "explicacao": "CF, art. 109, § 5º."}, {"id": 2000000384, "trilha": "policial", "materia": "dh", "assunto": "CF e direitos humanos", "tipo": "pergunta", "frente": "Que tribunal internacional o Brasil se submete por força da Constituição?", "verso": "O Tribunal Penal Internacional.", "explicacao": "CF, art. 5º, § 4º. Estatuto de Roma."}, {"id": 2000000385, "trilha": "policial", "materia": "dh", "assunto": "Tribunal Penal Internacional", "tipo": "pergunta", "frente": "Quais crimes o TPI julga?", "verso": "Genocídio, crimes contra a humanidade, crimes de guerra e crime de agressão.", "explicacao": "Estatuto de Roma, art. 5º."}, {"id": 2000000386, "trilha": "policial", "materia": "dh", "assunto": "Tribunal Penal Internacional", "tipo": "pergunta", "frente": "Qual o princípio que rege a atuação do TPI em relação às justiças nacionais?", "verso": "Complementaridade: só atua se o Estado não quiser ou não puder julgar.", "explicacao": "Estatuto de Roma, art. 17."}, {"id": 2000000387, "trilha": "policial", "materia": "dh", "assunto": "Pactos de 1966", "tipo": "pares", "frente": "Os dois pactos internacionais de 1966.", "verso": "Pacto Internacional sobre Direitos Civis e Políticos e Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais.", "explicacao": "Com a Declaração Universal, formam a Carta Internacional de Direitos Humanos."}, {"id": 2000000388, "trilha": "policial", "materia": "dh", "assunto": "Igualdade", "tipo": "pergunta", "frente": "O que são ações afirmativas?", "verso": "Medidas temporárias para acelerar a igualdade de fato de grupos historicamente discriminados.", "explicacao": "Ex.: cotas raciais em concursos (Lei 12.990/2014, constitucional segundo a ADC 41)."}, {"id": 2000000389, "trilha": "policial", "materia": "dh", "assunto": "Segurança pública", "tipo": "pergunta", "frente": "O que é o Sistema Único de Segurança Pública (SUSP)?", "verso": "Sistema que integra os órgãos de segurança da União, Estados, DF e Municípios, com atuação conjunta, coordenada e sistêmica.", "explicacao": "Lei 13.675/2018."}, {"id": 2000000390, "trilha": "policial", "materia": "dh", "assunto": "Grupos vulneráveis", "tipo": "pergunta", "frente": "Qual o princípio do melhor interesse da criança?", "verso": "Em todas as decisões que afetem crianças, deve prevalecer o que melhor atenda aos seus interesses.", "explicacao": "Convenção sobre os Direitos da Criança (1989), art. 3º."}, {"id": 2000000391, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é phishing?", "verso": "Golpe que usa mensagens ou sites falsos, imitando instituições conhecidas, para roubar senhas e dados.", "explicacao": "Engenharia social."}, {"id": 2000000392, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é ransomware?", "verso": "Malware que sequestra os dados (geralmente criptografando) e exige resgate para liberá-los.", "explicacao": "Backups atualizados são a principal defesa."}, {"id": 2000000393, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Vírus x worm.", "verso": "Vírus: precisa de um arquivo hospedeiro e de execução para se propagar. Worm: propaga-se sozinho pela rede, explorando falhas.", "explicacao": "Cavalo de Troia: parece legítimo e esconde uma função maliciosa."}, {"id": 2000000394, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é um keylogger?", "verso": "Programa espião que registra o que é digitado no teclado.", "explicacao": "Screenlogger: captura a tela ou a região clicada."}, {"id": 2000000395, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que faz um firewall?", "verso": "Filtra o tráfego da rede, permitindo ou bloqueando conexões conforme regras.", "explicacao": "Não é antivírus: não remove malware."}, {"id": 2000000396, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "Quais os pilares da segurança da informação (tríade CID)?", "verso": "Confidencialidade, integridade e disponibilidade.", "explicacao": "Acrescenta-se autenticidade e não repúdio."}, {"id": 2000000397, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pares", "frente": "Criptografia simétrica x assimétrica.", "verso": "Simétrica: a mesma chave cifra e decifra. Assimétrica: par de chaves pública e privada.", "explicacao": "A assinatura digital usa a chave privada de quem assina."}, {"id": 2000000398, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é autenticação em dois fatores?", "verso": "Exigir dois tipos de prova de identidade: algo que você sabe (senha), tem (celular, token) ou é (biometria).", "explicacao": "Reduz muito o risco de invasão por senha vazada."}, {"id": 2000000399, "trilha": "policial", "materia": "inf", "assunto": "Segurança", "tipo": "pergunta", "frente": "O que é backup incremental?", "verso": "Copia só o que mudou desde o último backup de qualquer tipo.", "explicacao": "Diferencial: copia o que mudou desde o último backup completo."}, {"id": 2000000400, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "Internet x intranet x extranet.", "verso": "Internet: rede pública mundial. Intranet: rede privada da organização, com tecnologias da internet. Extranet: parte da intranet acessível a parceiros externos.", "explicacao": "Todas usam TCP/IP."}, {"id": 2000000401, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "HTTP x HTTPS.", "verso": "HTTPS é o HTTP com criptografia (TLS), protegendo os dados trafegados.", "explicacao": "O cadeado no navegador indica conexão HTTPS."}, {"id": 2000000402, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "O que faz o DNS?", "verso": "Traduz nomes de domínio (ex.: gov.br) em endereços IP.", "explicacao": "Domain Name System."}, {"id": 2000000403, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pares", "frente": "Protocolos de e-mail: SMTP x POP3 x IMAP.", "verso": "SMTP: envia. POP3: baixa as mensagens para o dispositivo. IMAP: acessa as mensagens mantendo-as no servidor e sincronizadas.", "explicacao": "Clássico de prova."}, {"id": 2000000404, "trilha": "policial", "materia": "inf", "assunto": "Redes", "tipo": "pergunta", "frente": "Para que serve uma VPN?", "verso": "Criar um túnel criptografado sobre uma rede pública, simulando uma conexão privada.", "explicacao": "Muito usada para acesso remoto seguro à rede da instituição."}, {"id": 2000000405, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "O que é a navegação anônima (privada)?", "verso": "Não guarda histórico, cookies e dados de formulário após fechar a janela. Não torna o usuário anônimo para sites ou provedor.", "explicacao": "Downloads e favoritos continuam salvos."}, {"id": 2000000406, "trilha": "policial", "materia": "inf", "assunto": "Navegadores", "tipo": "pergunta", "frente": "O que são cookies?", "verso": "Pequenos arquivos que os sites gravam no navegador para lembrar preferências, sessões e rastrear navegação.", "explicacao": "Não são vírus."}, {"id": 2000000407, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "Atalho para alternar entre janelas abertas no Windows:", "verso": "Alt + Tab.", "explicacao": "Windows + D mostra a área de trabalho; Windows + L bloqueia o computador."}, {"id": 2000000408, "trilha": "policial", "materia": "inf", "assunto": "Windows", "tipo": "pergunta", "frente": "O que acontece com arquivo apagado com Shift + Delete?", "verso": "É excluído permanentemente, sem passar pela Lixeira.", "explicacao": "Pendrives e unidades de rede também não usam Lixeira."}, {"id": 2000000409, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que faz a fórmula =SOMA(A1:A5)?", "verso": "Soma os valores das células de A1 até A5.", "explicacao": "Dois-pontos = intervalo; ponto e vírgula = células separadas (A1;A5)."}, {"id": 2000000410, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pares", "frente": "Referência relativa x absoluta no Excel.", "verso": "Relativa (A1) muda ao copiar a fórmula. Absoluta ($A$1) não muda.", "explicacao": "$A1 trava a coluna; A$1 trava a linha."}, {"id": 2000000411, "trilha": "policial", "materia": "inf", "assunto": "Excel", "tipo": "pergunta", "frente": "O que retorna =SE(A1>=7;\"Aprovado\";\"Reprovado\") quando A1 = 6?", "verso": "Reprovado.", "explicacao": "Estrutura: =SE(teste;valor_se_verdadeiro;valor_se_falso)."}, {"id": 2000000412, "trilha": "policial", "materia": "inf", "assunto": "Word", "tipo": "pergunta", "frente": "Atalhos do Word para negrito, itálico e sublinhado:", "verso": "Ctrl + N, Ctrl + I e Ctrl + S (versão em português).", "explicacao": "Em inglês: Ctrl + B, Ctrl + I e Ctrl + U."}, {"id": 2000000413, "trilha": "policial", "materia": "inf", "assunto": "Nuvem", "tipo": "pares", "frente": "IaaS x PaaS x SaaS.", "verso": "IaaS: infraestrutura (servidores virtuais). PaaS: plataforma para desenvolver e rodar aplicações. SaaS: software pronto usado pela internet (ex.: e-mail web).", "explicacao": "Modelos de serviço de computação em nuvem."}, {"id": 2000000414, "trilha": "policial", "materia": "inf", "assunto": "Hardware", "tipo": "pares", "frente": "Memória RAM x ROM.", "verso": "RAM: volátil, guarda dados temporários em uso. ROM: não volátil, guarda instruções permanentes (como o firmware).", "explicacao": "Desligou o computador, a RAM se apaga."}, {"id": 2000000415, "trilha": "policial", "materia": "inf", "assunto": "Busca", "tipo": "pergunta", "frente": "No Google, o que faz colocar a expressão entre aspas?", "verso": "Busca exatamente aquela sequência de palavras.", "explicacao": "Sinal de menos exclui termo (-palavra); site: restringe a um domínio."}, {"id": 2000000416, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “P e Q”:", "verso": "“não P ou não Q”.", "explicacao": "Lei de De Morgan: ~(P ∧ Q) ≡ ~P ∨ ~Q."}, {"id": 2000000417, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “P ou Q”:", "verso": "“não P e não Q”.", "explicacao": "Lei de De Morgan: ~(P ∨ Q) ≡ ~P ∧ ~Q."}, {"id": 2000000418, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Negação de “Se P, então Q”:", "verso": "“P e não Q”.", "explicacao": "~(P → Q) ≡ P ∧ ~Q. A negação de condicional nunca é outra condicional."}, {"id": 2000000419, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Equivalências de “Se P, então Q”:", "verso": "“Se não Q, então não P” (contrapositiva) e “não P ou Q”.", "explicacao": "P → Q ≡ ~Q → ~P ≡ ~P ∨ Q."}, {"id": 2000000420, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a condicional “Se P, então Q” é falsa?", "verso": "Só quando P é verdadeira e Q é falsa.", "explicacao": "Mnemônico: “Vera Fischer é falsa” (V → F = F)."}, {"id": 2000000421, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a bicondicional “P se e somente se Q” é verdadeira?", "verso": "Quando P e Q têm o mesmo valor lógico (ambas V ou ambas F).", "explicacao": "P ↔ Q."}, {"id": 2000000422, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quando a disjunção exclusiva “ou P ou Q” é verdadeira?", "verso": "Quando P e Q têm valores diferentes.", "explicacao": "É a negação da bicondicional."}, {"id": 2000000423, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pergunta", "frente": "Quantas linhas tem a tabela-verdade de uma proposição com n proposições simples?", "verso": "2 elevado a n.", "explicacao": "Ex.: 3 proposições → 8 linhas."}, {"id": 2000000424, "trilha": "policial", "materia": "rl", "assunto": "Proposições", "tipo": "pares", "frente": "Tautologia x contradição x contingência.", "verso": "Tautologia: sempre verdadeira. Contradição: sempre falsa. Contingência: pode ser V ou F.", "explicacao": "Ex.: “P ou não P” é tautologia."}, {"id": 2000000425, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Todo A é B”:", "verso": "“Algum A não é B”.", "explicacao": "Também: “Existe A que não é B”."}, {"id": 2000000426, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Nenhum A é B”:", "verso": "“Algum A é B”.", "explicacao": "Também: “Existe A que é B”."}, {"id": 2000000427, "trilha": "policial", "materia": "rl", "assunto": "Quantificadores", "tipo": "pergunta", "frente": "Negação de “Algum A é B”:", "verso": "“Nenhum A é B”.", "explicacao": "Não confundir com “Algum A não é B”."}, {"id": 2000000428, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pergunta", "frente": "O que é um argumento válido?", "verso": "Aquele em que, se as premissas forem verdadeiras, a conclusão é necessariamente verdadeira.", "explicacao": "Validade depende da forma, não da verdade das premissas."}, {"id": 2000000429, "trilha": "policial", "materia": "rl", "assunto": "Argumentação", "tipo": "pares", "frente": "Modus ponens x modus tollens.", "verso": "Ponens: P → Q; P; logo Q. Tollens: P → Q; não Q; logo não P.", "explicacao": "Falácias: afirmar o consequente e negar o antecedente."}, {"id": 2000000430, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Como calcular o número de anagramas de uma palavra sem letras repetidas?", "verso": "Fatorial do número de letras (n!).", "explicacao": "Com repetição, divide pelo fatorial das repetições: ARARA = 5!/(3!·2!) = 10."}, {"id": 2000000431, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pares", "frente": "Arranjo x combinação.", "verso": "Arranjo: a ordem importa (pódio, senha). Combinação: a ordem não importa (comissão, grupo).", "explicacao": "C(n,p) = n! / (p!·(n−p)!)."}, {"id": 2000000432, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Quantas duplas diferentes podem ser formadas com 8 pessoas?", "verso": "28.", "explicacao": "C(8,2) = 8·7/2."}, {"id": 2000000433, "trilha": "policial", "materia": "rl", "assunto": "Contagem", "tipo": "pergunta", "frente": "Princípio da casa dos pombos: quantas pessoas garantem duas nascidas no mesmo mês?", "verso": "13.", "explicacao": "12 meses + 1."}, {"id": 2000000434, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Como se calcula a probabilidade de um evento?", "verso": "Casos favoráveis divididos pelos casos possíveis.", "explicacao": "P = favoráveis / possíveis, entre 0 e 1."}, {"id": 2000000435, "trilha": "policial", "materia": "rl", "assunto": "Probabilidade", "tipo": "pares", "frente": "Probabilidade de “A e B” (independentes) x “A ou B” (excludentes).", "verso": "“E”: multiplica as probabilidades. “Ou” (mutuamente excludentes): soma.", "explicacao": "Ex.: dois lançamentos de moeda darem cara: 1/2 · 1/2 = 1/4."}, {"id": 2000000436, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Aumento de 10% seguido de desconto de 10%: o preço final volta ao original?", "verso": "Não. Fica 1% menor (1,1 × 0,9 = 0,99).", "explicacao": "Aumentos e descontos sucessivos se multiplicam, não se somam."}, {"id": 2000000437, "trilha": "policial", "materia": "rl", "assunto": "Porcentagem", "tipo": "pergunta", "frente": "Descontos sucessivos de 10% e 20% equivalem a quanto?", "verso": "28%.", "explicacao": "0,9 × 0,8 = 0,72 → restam 72%."}, {"id": 2000000438, "trilha": "policial", "materia": "rl", "assunto": "Juros", "tipo": "pares", "frente": "Juros simples x compostos.", "verso": "Simples: juros sempre sobre o capital inicial (crescimento linear). Compostos: juros sobre juros (crescimento exponencial).", "explicacao": "M = C(1 + i·t) x M = C(1 + i)^t."}, {"id": 2000000439, "trilha": "policial", "materia": "rl", "assunto": "Sequências", "tipo": "pergunta", "frente": "Qual o termo geral de uma progressão aritmética?", "verso": "aₙ = a₁ + (n − 1)·r.", "explicacao": "Soma: Sₙ = (a₁ + aₙ)·n / 2."}, {"id": 2000000440, "trilha": "policial", "materia": "rl", "assunto": "Conjuntos", "tipo": "pergunta", "frente": "Como calcular o número de elementos da união de dois conjuntos?", "verso": "n(A ∪ B) = n(A) + n(B) − n(A ∩ B).", "explicacao": "Subtrai a interseção para não contá-la duas vezes."}, {"id": 2000000441, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pares", "frente": "Instrumentos perfurantes, cortantes e contundentes: que lesão produzem?", "verso": "Perfurante (agulha): punctória. Cortante (navalha): incisa. Contundente (bastão): contusa.", "explicacao": "Combinações: perfurocortante (faca) = perfuroincisa; cortocontundente (machado) = cortocontusa; perfurocontundente (projétil) = perfurocontusa."}, {"id": 2000000442, "trilha": "policial", "materia": "ml", "assunto": "Traumatologia", "tipo": "pergunta", "frente": "Que lesão produz um projétil de arma de fogo?", "verso": "Perfurocontusa.", "explicacao": "Instrumento perfurocontundente."}, {"id": 2000000443, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pares", "frente": "Ferida de entrada x ferida de saída do projétil.", "verso": "Entrada: geralmente menor, bordas invertidas, orla de escoriação e enxugo. Saída: maior, irregular, bordas evertidas, sem orlas.", "explicacao": "A orla de enxugo é a sujeira do projétil deixada na pele."}, {"id": 2000000444, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que caracteriza o tiro encostado?", "verso": "Ferida irregular e estrelada (câmara de mina de Hoffmann) e sinal de Puppe-Werkgaertner (marca da boca do cano).", "explicacao": "Os gases penetram sob a pele e a rompem."}, {"id": 2000000445, "trilha": "policial", "materia": "ml", "assunto": "Balística", "tipo": "pergunta", "frente": "O que indicam a zona de tatuagem e a zona de esfumaçamento?", "verso": "Tiro a curta distância. A tatuagem (grãos de pólvora incrustados) não sai com lavagem; o esfumaçamento (fuligem) sai.", "explicacao": "Ausência de ambas sugere tiro a distância."}, {"id": 2000000446, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Qual a ordem de surgimento da rigidez cadavérica (Lei de Nysten)?", "verso": "Começa pela mandíbula e nuca, desce para tronco e membros superiores e depois inferiores.", "explicacao": "Inicia em 1 a 2 horas e se completa em cerca de 8 horas."}, {"id": 2000000447, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Quando surgem e quando se fixam os livores cadavéricos?", "verso": "Surgem em 2 a 3 horas e se fixam em cerca de 8 a 12 horas.", "explicacao": "Ficam nas partes de declive; ajudam a saber se o corpo foi mudado de posição."}, {"id": 2000000448, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "Qual o primeiro sinal da putrefação?", "verso": "A mancha verde abdominal, geralmente na fossa ilíaca direita, entre 18 e 24 horas.", "explicacao": "Fases: cromática, gasosa, coliquativa e esqueletização."}, {"id": 2000000449, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Fenômenos transformativos destrutivos x conservadores.", "verso": "Destrutivos: autólise, putrefação, maceração. Conservadores: mumificação, saponificação (adipocera), corificação.", "explicacao": "Mumificação: ambiente quente e seco; saponificação: úmido e argiloso."}, {"id": 2000000450, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é cronotanatognose?", "verso": "A estimativa do tempo de morte.", "explicacao": "Usa resfriamento, rigidez, livores, putrefação, entre outros."}, {"id": 2000000451, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pares", "frente": "Enforcamento x estrangulamento x esganadura.", "verso": "Enforcamento: laço acionado pelo peso do corpo. Estrangulamento: laço acionado por força externa. Esganadura: compressão do pescoço com as mãos.", "explicacao": "Esganadura é sempre homicida."}, {"id": 2000000452, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "Como é o sulco do enforcamento típico?", "verso": "Oblíquo, ascendente em direção ao nó, descontínuo e mais profundo do lado oposto ao nó.", "explicacao": "No estrangulamento, o sulco é horizontal e contínuo."}, {"id": 2000000453, "trilha": "policial", "materia": "ml", "assunto": "Asfixiologia", "tipo": "pergunta", "frente": "O que é o cogumelo de espuma?", "verso": "Espuma branca e fina na boca e nariz, típica do afogamento com o corpo vivo ao entrar na água.", "explicacao": "Sinal de vitalidade no afogamento."}, {"id": 2000000454, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pergunta", "frente": "O que é equimose e como evolui sua cor (espectro de Legrand du Saulle)?", "verso": "Extravasamento de sangue na pele. Cores: vermelha, violácea, azul, esverdeada e amarelada, até desaparecer.", "explicacao": "Ajuda a datar a lesão."}, {"id": 2000000455, "trilha": "policial", "materia": "ml", "assunto": "Lesões", "tipo": "pares", "frente": "Equimose x hematoma.", "verso": "Equimose: sangue infiltrado nos tecidos, sem formar coleção. Hematoma: coleção de sangue que forma relevo.", "explicacao": "O hematoma pode ser puncionado."}, {"id": 2000000456, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "Que lesão é produzida por descarga elétrica de alta tensão natural (raio)?", "verso": "Sinal de Lichtenberg: figuras arboriformes na pele.", "explicacao": "Na energia elétrica industrial, a marca típica é a de Jellinek."}, {"id": 2000000457, "trilha": "policial", "materia": "ml", "assunto": "Energias", "tipo": "pergunta", "frente": "Quais os graus de queimadura?", "verso": "1º: eritema. 2º: flictena (bolhas). 3º: necrose de toda a pele. 4º: carbonização.", "explicacao": "Classificação de Hoffmann."}, {"id": 2000000458, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Qual o método de identificação mais usado pela papiloscopia?", "verso": "Datiloscopia: análise das impressões digitais (sistema de Vucetich).", "explicacao": "Baseia-se na perenidade, imutabilidade, variabilidade e classificabilidade."}, {"id": 2000000459, "trilha": "policial", "materia": "ml", "assunto": "Identificação", "tipo": "pergunta", "frente": "Quais os tipos fundamentais de impressão digital no sistema de Vucetich?", "verso": "Arco, presilha interna, presilha externa e verticilo.", "explicacao": "Arco não tem delta; presilhas têm um delta; verticilo tem dois."}, {"id": 2000000460, "trilha": "policial", "materia": "ml", "assunto": "Sexologia", "tipo": "pergunta", "frente": "O que é conjunção carnal para fins penais?", "verso": "A penetração do pênis na vagina, ainda que parcial.", "explicacao": "Outros atos são “ato libidinoso diverso”."}, {"id": 2000000461, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pares", "frente": "Laudo x auto x parecer.", "verso": "Laudo: relatório escrito pelos próprios peritos. Auto: ditado pelo perito a um escrivão, durante o exame. Parecer: opinião técnica sobre um laudo, a pedido de alguém.", "explicacao": "Documentos médico-legais."}, {"id": 2000000462, "trilha": "policial", "materia": "ml", "assunto": "Documentos", "tipo": "pergunta", "frente": "Quais as partes do laudo pericial?", "verso": "Preâmbulo, quesitos, histórico, descrição, discussão, conclusão e resposta aos quesitos.", "explicacao": "A descrição (visum et repertum) é a parte mais importante."}, {"id": 2000000463, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pares", "frente": "Morte encefálica: o que é?", "verso": "Parada total e irreversível das funções do encéfalo, que autoriza a retirada de órgãos para transplante.", "explicacao": "Lei 9.434/1997 e Resolução CFM 2.173/2017."}, {"id": 2000000464, "trilha": "policial", "materia": "ml", "assunto": "Tanatologia", "tipo": "pergunta", "frente": "O que é comoriência?", "verso": "Presunção de morte simultânea de duas ou mais pessoas, quando não se sabe quem morreu primeiro.", "explicacao": "Código Civil, art. 8º."}, {"id": 2000000465, "trilha": "policial", "materia": "ml", "assunto": "Toxicologia", "tipo": "pergunta", "frente": "Qual o efeito do monóxido de carbono no sangue e que sinal deixa no cadáver?", "verso": "Liga-se à hemoglobina (carboxiemoglobina), impedindo o transporte de oxigênio. Deixa livores de cor vermelho-carmim.", "explicacao": "Intoxicação comum em incêndios e ambientes fechados."}, {"id": 2000000466, "trilha": "policial", "materia": "est", "assunto": "Medidas", "tipo": "pares", "frente": "Média x mediana x moda.", "verso": "Média: soma dividida pela quantidade. Mediana: valor central dos dados ordenados. Moda: valor que mais se repete.", "explicacao": "A mediana sofre menos influência de valores extremos."}, {"id": 2000000467, "trilha": "policial", "materia": "est", "assunto": "Dispersão", "tipo": "pergunta", "frente": "Qual a relação entre variância e desvio padrão?", "verso": "O desvio padrão é a raiz quadrada da variância.", "explicacao": "O desvio padrão fica na mesma unidade dos dados."}, {"id": 2000000468, "trilha": "policial", "materia": "est", "assunto": "Dispersão", "tipo": "pergunta", "frente": "O que é a amplitude de um conjunto de dados?", "verso": "A diferença entre o maior e o menor valor.", "explicacao": "Medida de dispersão mais simples."}, {"id": 2000000469, "trilha": "policial", "materia": "est", "assunto": "Variáveis", "tipo": "pares", "frente": "Variável qualitativa x quantitativa.", "verso": "Qualitativa: atributos (cor, sexo, tipo de crime). Quantitativa: números (idade, número de ocorrências).", "explicacao": "Quantitativa discreta (contagem) ou contínua (medição)."}, {"id": 2000000470, "trilha": "policial", "materia": "est", "assunto": "Amostragem", "tipo": "pares", "frente": "População x amostra.", "verso": "População: todo o conjunto de interesse. Amostra: parte da população usada para estudá-la.", "explicacao": "Parâmetro descreve a população; estatística, a amostra."}, {"id": 2000000471, "trilha": "policial", "materia": "cont", "assunto": "Fundamentos", "tipo": "pergunta", "frente": "Qual a equação fundamental do patrimônio?", "verso": "Ativo = Passivo + Patrimônio Líquido.", "explicacao": "O patrimônio líquido é a riqueza própria."}, {"id": 2000000472, "trilha": "policial", "materia": "cont", "assunto": "Contas", "tipo": "pares", "frente": "Contas de natureza devedora x credora.", "verso": "Devedoras: ativo e despesas. Credoras: passivo, patrimônio líquido e receitas.", "explicacao": "Contas retificadoras têm natureza contrária ao grupo."}, {"id": 2000000473, "trilha": "policial", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Qual o método de escrituração contábil adotado no Brasil?", "verso": "Método das partidas dobradas: não há débito sem crédito de igual valor.", "explicacao": "Atribuído a Luca Pacioli."}, {"id": 2000000474, "trilha": "policial", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "O que mostra o balanço patrimonial?", "verso": "A posição patrimonial e financeira da entidade numa data: ativo, passivo e patrimônio líquido.", "explicacao": "A DRE mostra o resultado do período."}, {"id": 2000000475, "trilha": "policial", "materia": "cont", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é o regime de competência?", "verso": "Receitas e despesas são reconhecidas no período em que ocorrem, independentemente de recebimento ou pagamento.", "explicacao": "O regime de caixa considera a entrada e saída de dinheiro."}, {"id": 2000000476, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "Como o Estatuto da Igualdade Racial define a população negra?", "verso": "O conjunto de pessoas que se autodeclaram pretas e pardas, conforme o quesito cor ou raça do IBGE.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, IV."}, {"id": 2000000477, "trilha": "policial", "materia": "igual", "assunto": "Estatuto da Igualdade Racial", "tipo": "pergunta", "frente": "O que é discriminação racial pelo Estatuto?", "verso": "Toda distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica que anule ou restrinja direitos em igualdade de condições.", "explicacao": "Lei 12.288/2010, art. 1º, parágrafo único, I."}, {"id": 2000000478, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pares", "frente": "Racismo x injúria racial hoje.", "verso": "Os dois são crimes de racismo: inafiançáveis e imprescritíveis. Injúria racial ofende a pessoa determinada; racismo atinge a coletividade (ex.: impedir acesso a lugar).", "explicacao": "Lei 7.716/1989, com a Lei 14.532/2023."}, {"id": 2000000479, "trilha": "policial", "materia": "igual", "assunto": "Racismo", "tipo": "pergunta", "frente": "O que é racismo recreativo?", "verso": "Injúria racial praticada em contexto de descontração, diversão ou recreação. Gera aumento de pena.", "explicacao": "Lei 7.716/1989, art. 20-A (Lei 14.532/2023)."}, {"id": 2000000480, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O STF equiparou a homofobia e a transfobia a quê?", "verso": "Ao crime de racismo, até que o Congresso edite lei específica.", "explicacao": "STF, ADO 26 e MI 4.733 (2019)."}, {"id": 2000000481, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pares", "frente": "Identidade de gênero x orientação sexual.", "verso": "Identidade de gênero: como a pessoa se reconhece (homem, mulher, outro). Orientação sexual: por quem sente atração afetiva e sexual.", "explicacao": "São conceitos independentes."}, {"id": 2000000482, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é a Lei do Minuto Seguinte?", "verso": "Lei que garante atendimento imediato, obrigatório e integral no SUS às vítimas de violência sexual.", "explicacao": "Lei 12.845/2013."}, {"id": 2000000483, "trilha": "policial", "materia": "igual", "assunto": "Gênero", "tipo": "pergunta", "frente": "O que é violência política contra a mulher?", "verso": "Ação ou omissão para impedir, obstaculizar ou restringir os direitos políticos da mulher.", "explicacao": "Lei 14.192/2021."}, {"id": 2000000484, "trilha": "policial", "materia": "igual", "assunto": "Igualdade", "tipo": "pergunta", "frente": "As cotas raciais em concursos federais são constitucionais?", "verso": "Sim, segundo o STF.", "explicacao": "STF, ADC 41, que julgou constitucional a reserva de vagas da Lei 12.990/2014."}, {"id": 2000000485, "trilha": "policial", "materia": "igual", "assunto": "Povos tradicionais", "tipo": "pergunta", "frente": "Qual o órgão federal responsável pela política indigenista?", "verso": "A Funai (Fundação Nacional dos Povos Indígenas).", "explicacao": "Vinculada ao Ministério dos Povos Indígenas."}, {"id": 2000000486, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Como o Estatuto define a pessoa com deficiência?", "verso": "Quem tem impedimento de longo prazo de natureza física, mental, intelectual ou sensorial que, em interação com barreiras, pode obstruir sua participação plena na sociedade em igualdade de condições.", "explicacao": "Lei 13.146/2015, art. 2º."}, {"id": 2000000487, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "certo_errado", "frente": "Certo ou errado? A deficiência afeta a plena capacidade civil da pessoa.", "verso": "Errado.", "explicacao": "Lei 13.146/2015, art. 6º."}, {"id": 2000000488, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "O que é adaptação razoável?", "verso": "Adaptações e ajustes necessários e adequados, sem ônus desproporcional, para garantir que a pessoa com deficiência exerça seus direitos em igualdade.", "explicacao": "Lei 13.146/2015, art. 3º, VI."}, {"id": 2000000489, "trilha": "policial", "materia": "pcd", "assunto": "Estatuto da Pessoa com Deficiência", "tipo": "pergunta", "frente": "Qual o crime previsto para quem discrimina pessoa em razão de sua deficiência?", "verso": "Reclusão de 1 a 3 anos e multa.", "explicacao": "Lei 13.146/2015, art. 88."}, {"id": 2000000490, "trilha": "policial", "materia": "pcd", "assunto": "Convenção", "tipo": "pergunta", "frente": "Qual o status da Convenção da ONU sobre os Direitos das Pessoas com Deficiência no Brasil?", "verso": "Equivalente a emenda constitucional, por ter sido aprovada com o rito do art. 5º, § 3º.", "explicacao": "Decreto 6.949/2009."}, {"id": 2000000491, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é aprendizado de máquina (machine learning)?", "verso": "Área da IA em que sistemas aprendem padrões a partir de dados, sem ser programados regra por regra.", "explicacao": "Ex.: reconhecimento facial, filtros de spam."}, {"id": 2000000492, "trilha": "policial", "materia": "ia", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é IA generativa?", "verso": "Sistemas que criam conteúdo novo (texto, imagem, áudio, vídeo) a partir de padrões aprendidos.", "explicacao": "Ex.: chatbots e geradores de imagem."}, {"id": 2000000493, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é deepfake?", "verso": "Vídeo, áudio ou imagem falsos, gerados ou alterados por IA, que imitam pessoas reais.", "explicacao": "Risco para fraudes, golpes e desinformação."}, {"id": 2000000494, "trilha": "policial", "materia": "ia", "assunto": "Riscos", "tipo": "pergunta", "frente": "O que é viés algorítmico?", "verso": "Quando o sistema reproduz ou amplia preconceitos presentes nos dados de treinamento.", "explicacao": "Preocupação no uso de reconhecimento facial na segurança pública."}, {"id": 2000000495, "trilha": "policial", "materia": "ia", "assunto": "Proteção de dados", "tipo": "pergunta", "frente": "Dados biométricos são que tipo de dado pessoal na LGPD?", "verso": "Dados pessoais sensíveis.", "explicacao": "Lei 13.709/2018, art. 5º, II."}, {"id": 2000000496, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é desenvolvimento sustentável?", "verso": "Atender às necessidades do presente sem comprometer a capacidade das futuras gerações de atenderem às suas.", "explicacao": "Relatório Brundtland (1987)."}, {"id": 2000000497, "trilha": "policial", "materia": "sust", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais os três pilares da sustentabilidade?", "verso": "Ambiental, social e econômico.", "explicacao": "Base do conceito de ESG."}, {"id": 2000000498, "trilha": "policial", "materia": "sust", "assunto": "Agenda 2030", "tipo": "pergunta", "frente": "Quantos são os Objetivos de Desenvolvimento Sustentável da ONU?", "verso": "17 objetivos.", "explicacao": "Agenda 2030. O ODS 16 trata de paz, justiça e instituições eficazes."}, {"id": 2000000499, "trilha": "policial", "materia": "sust", "assunto": "Gestão pública", "tipo": "pergunta", "frente": "O que é a A3P?", "verso": "Agenda Ambiental na Administração Pública, programa para adotar práticas sustentáveis nos órgãos públicos.", "explicacao": "Coordenada pelo Ministério do Meio Ambiente."}, {"id": 2000000500, "trilha": "policial", "materia": "sust", "assunto": "Constituição", "tipo": "pergunta", "frente": "A quem a Constituição impõe o dever de defender o meio ambiente?", "verso": "Ao Poder Público e à coletividade, para as presentes e futuras gerações.", "explicacao": "CF, art. 225."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
